import React from 'react';
import { Box, Button } from '@mui/material';

// MODIFY — THE OCTAGON PAD (Round 36.5, Eddie 2026-11-19
// ~12:10–12:11 PT + ~14:41 PT): the crystal tints move OUT of
// the bottom "Modify <name>" panel and onto an octagon pad that
// pops up on the LEFT of the Stage's picture, mirroring the
// thumb cluster on the right — across the screen adjacent, the
// character standing between the two clusters, so recolouring
// never makes the player look away from their navitar. The
// bottom panel is deleted entirely (Eddie: it "makes you look
// away from the character while you're changing its color").
//
// PLACEMENT (Round 36.8, Eddie 2026-11-19 ~18:38 PT): the pad
// moves DOWN. It no longer floats at stage height — it anchors
// at the picture's bottom-LEFT corner, at the exact level of
// the thumb cluster at the bottom-right: the two controllers
// mirrored across the screen like a gamepad in two hands (left
// thumb / right thumb), low enough that NEITHER controller
// overlaps the navitar — the character stands clear in the
// center. ONLY the seat changed: the pad's design, tints,
// glass, seats and behaviour are exactly the Round 36.5 pad
// (Eddie: "the color pallet is perfect").
//
// SIGNATURE CONTROLLER (Eddie's standing design law, restated
// 2026-11-19): GLACER's octagon D-pad controller is ICONIC —
// this pad is not a generic pop-up. It is built from the thumb
// cluster's own parts: the same 120px octagon footprint (Round 36.9: the pair shrank together from 148px), the
// same 42px glass circles (translucent deep-teal, one thin ice
// border, backdrop blur, the deep soft shadow), the same 46px
// centre hub, the same micro-label typography, the same gold
// ring for the active node, the same hover wash, the same press
// feel. The two Stage clusters read as a matched pair of ONE
// controller system. (The battle octagon D-pad is a different,
// LOCKED control — nothing here touches it.)
//
// Behaviour (the Save/Close law): a tint tap PREVIEWS — the
// Stage repaints its model's tint filter live and writes
// NOTHING. Save persists the previewed tint through the same
// care-record field the old panel wrote (care.tint) and closes
// the pad. Close discards every previewed change and closes.
// Gear/armour has NO UI on this pad yet (Eddie, 2026-11-19
// ~14:42 PT: add-ons come later as a drop-down inside this
// pad) — gear data in the care record stays dormant.

// The crystal tints (moved here from NavidexStage with the
// control itself — same labels, same CSS filter strings, so
// every care record ever saved keeps its exact meaning). Each
// tint also carries the colour its pad button wears.
export const CRYSTAL_TINTS: { label: string; short: string; filter: string; swatch: string }[] = [
  {
    label: 'True colours',
    short: 'True',
    filter: 'none',
    swatch: 'linear-gradient(135deg, #ffffff, #a8c8d8)',
  },
  {
    label: 'Frost crystal',
    short: 'Frost',
    filter: 'hue-rotate(150deg) saturate(1.3)',
    swatch: 'linear-gradient(135deg, #bdeaff, #4fb6ff)',
  },
  {
    label: 'Ember crystal',
    short: 'Ember',
    filter: 'hue-rotate(-35deg) saturate(1.5)',
    swatch: 'linear-gradient(135deg, #ffc46b, #ff6a3d)',
  },
  {
    label: 'Void crystal',
    short: 'Void',
    filter: 'hue-rotate(240deg) saturate(1.2) brightness(0.9)',
    swatch: 'linear-gradient(135deg, #c9a6ff, #5b2ea6)',
  },
  {
    label: 'Gilded',
    short: 'Gilded',
    filter: 'sepia(0.7) saturate(2) hue-rotate(5deg)',
    swatch: 'linear-gradient(135deg, #fff3b0, #f5b921)',
  },
];

const slug = (label: string) => label.toLowerCase().replace(/\s+/g, '-');

// The shared glass of the controller family — one recipe, copied
// from the thumb cluster's nodes so the pair can never drift.
const glassSx = {
  position: 'absolute' as const,
  transform: 'translate(-50%, -50%)',
  width: 36,
  height: 36,
  minWidth: 0,
  borderRadius: '50%',
  flexDirection: 'column' as const,
  gap: 0,
  p: 0.25,
  lineHeight: 1.05,
  textTransform: 'none' as const,
  color: '#eaf6fa',
  bgcolor: 'rgba(13, 47, 63, 0.55)',
  border: '1px solid rgba(120,200,225,0.34)',
  boxShadow: '0 6px 18px rgba(0, 0, 0, 0.45)',
  backdropFilter: 'blur(10px)',
  WebkitBackdropFilter: 'blur(10px)',
  '&:hover': { bgcolor: 'rgba(18, 165, 199, 0.35)' },
};

const activeSx = {
  border: '2px solid #ffd54f',
  boxShadow: '0 0 16px rgba(255,213,79,0.5)',
};

interface ModifyPadProps {
  fighterName: string;
  // The tint filter currently being previewed (the pad opened
  // with the committed tint; taps move the preview only).
  preview: string;
  onPreview: (filter: string) => void;
  onSave: () => void;
  onClose: () => void;
}

export const ModifyPad: React.FC<ModifyPadProps> = ({
  fighterName,
  preview,
  onPreview,
  onSave,
  onClose,
}) => {
  // Octagon seats (percent centres in the 120px pad): the five
  // tints take the arc that faces the character — N, NE, E, SE,
  // S — Save sits SW (the commit seat), Close sits W (the
  // Modify seat mirrored: out the way you came in), and NW
  // carries the pad's title crystal, a non-interactive node in
  // the same glass so the octagon stays whole.
  const tintSeats = [
    { left: '50%', top: '13%' },
    { left: '76%', top: '24%' },
    { left: '87%', top: '50%' },
    { left: '76%', top: '76%' },
    { left: '50%', top: '87%' },
  ];
  return (
    <Box
      data-testid="stage-modify-pad"
      data-noswipe="true"
      role="group"
      aria-label={`Modify ${fighterName} — crystal tint pad`}
      sx={{
        position: 'absolute',
        // Round 36.8: seated in the picture's bottom-LEFT
        // corner at a 2px inset — the cluster eases to the
        // same 2px inset on the right while the pad is open,
        // so the pair mirrors exactly (gamepad geometry) and
        // neither crosses the centre: the character stands
        // clear between them. (The pad opens only in the
        // Stage's focus mode, where the picture window has
        // the height the pair needs.)
        left: 2,
        // Anchored to the picture's bottom edge — bottom: 10,
        // the thumb cluster's own seat line, so the pair sits
        // level across the screen from each other.
        bottom: 10,
        width: 120,
        height: 120,
        zIndex: 7,
      }}
    >
      {/* Centre hub — the cluster hub's twin: 46px of the same
          glass, carrying the Modify spark. */}
      <Box
        aria-hidden
        sx={{
          position: 'absolute',
          left: '50%',
          top: '50%',
          width: 40,
          height: 40,
          borderRadius: '50%',
          transform: 'translate(-50%, -50%)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '1.3rem',
          bgcolor: 'rgba(13, 47, 63, 0.55)',
          border: '1px solid rgba(120,200,225,0.34)',
          boxShadow: '0 6px 18px rgba(0, 0, 0, 0.45)',
          backdropFilter: 'blur(10px)',
          WebkitBackdropFilter: 'blur(10px)',
        }}
      >
        ✨
      </Box>
      {/* NW title node — the pad's name in glass, not a control. */}
      <Box
        aria-hidden
        sx={{
          ...glassSx,
          left: '24%',
          top: '24%',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '0.95rem',
        }}
      >
        🔮
      </Box>
      {CRYSTAL_TINTS.map((t, i) => {
        const selected = preview === t.filter;
        return (
          <Button
            key={t.label}
            data-testid={`stage-modify-tint-${slug(t.label)}`}
            aria-label={`${t.label} tint for ${fighterName}`}
            aria-pressed={selected}
            onClick={() => onPreview(t.filter)}
            sx={{
              ...glassSx,
              left: tintSeats[i].left,
              top: tintSeats[i].top,
              ...(selected ? activeSx : {}),
            }}
          >
            <span
              aria-hidden
              style={{
                width: 17,
                height: 17,
                borderRadius: '50%',
                background: t.swatch,
                border: '1px solid rgba(255,255,255,0.65)',
                boxShadow: '0 0 6px rgba(255,255,255,0.35)',
                display: 'block',
              }}
            />
            <span style={{ fontSize: '0.56rem', fontWeight: 800 }}>{t.short}</span>
          </Button>
        );
      })}
      <Button
        data-testid="stage-modify-save"
        aria-label={`Save tint for ${fighterName}`}
        onClick={onSave}
        sx={{
          ...glassSx,
          left: '24%',
          top: '76%',
          border: '2px solid #ffd54f',
          boxShadow: '0 0 16px rgba(255,213,79,0.45)',
        }}
      >
        <span style={{ fontSize: '0.95rem', lineHeight: 1.05 }}>✓</span>
        <span style={{ fontSize: '0.56rem', fontWeight: 800 }}>Save</span>
      </Button>
      <Button
        data-testid="stage-modify-close"
        aria-label="Close the Modify pad without saving"
        onClick={onClose}
        sx={{ ...glassSx, left: '13%', top: '50%' }}
      >
        <span style={{ fontSize: '0.95rem', lineHeight: 1.05 }}>✕</span>
        <span style={{ fontSize: '0.56rem', fontWeight: 800 }}>Close</span>
      </Button>
    </Box>
  );
};

export default ModifyPad;
