import React, { useEffect, useRef, useState } from 'react';
import { Box, Button, Container, Paper, Switch, Typography } from '@mui/material';
import { Link as RouterLink, useNavigate } from 'react-router-dom';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';
import { useVenue } from '../contexts/VenueContext';
import { NavitarArtImg } from '../components/NavitarArtImg';
import { NavidexSwapButton } from '../components/QuickSwapNavitar';
import { elementEmoji, resolveNavitarArt } from '../utils/navitarArt';
import { resolveShowcaseModel } from '../utils/modelResolution';
import {
  loadChallengeHandoff,
  saveChallengeHandoff,
  type ChallengeHandoff,
} from '../utils/challengeHandoff';
import {
  realmStageLine,
  rollRealmElement,
  venueRealmElement,
  type DuelRealm,
} from '../utils/realm';
import { supabase, type NavitarSnapshot } from '../utils/supabaseClient';
import { useAuth } from '../contexts/AuthContext';
import { usePresence } from '../contexts/PresenceContext';
import { navitarSnapshot } from '../utils/onlineFriends';
import {
  createBattleSession,
  fetchSessionForChallenge,
  joinBattleSession,
  type BattleSessionRow,
} from '../utils/battleSession';
import { useFriendPresence } from '../utils/friendPresence';
import type { Element } from '../data/venues';

// The challenge screen (Round 10, Eddie 2026-11-17): ONE screen for
// every "battle someone you met" flow — World Map meet card,
// Networking people, Friends rows, Profile friend challenges. The
// pairing is ALREADY MADE here: your active navitar vs their
// fighter, read from the persisted challenge handoff
// (utils/challengeHandoff.ts), so the screen survives reloads and
// the detour that used to lose the pairing (go choose a fighter,
// come back to nothing) cannot happen: the handoff persists, so
// the pairing is rebuilt from it after any detour. Round 14
// (Eddie, 2026-11-17): swapping here goes STRAIGHT TO THE
// NAVIDEX (NavidexSwapButton + the swap-return context in
// utils/swapReturn.ts) — pick with the ✓ there, tap "Back to
// your battle →", and this screen is waiting with the pairing
// intact.
//
// This screen IS the opponent-approval step for meet challenges
// (battle law: nothing auto-starts). Pressing ⚔️ Battle hands the
// Battle page the venue pending-challenge plus the handoff's
// directStart flag, and the duel starts against exactly this
// opponent — no second gate. The solo /battle entry flow (wild
// picker, Steps 1–3) is untouched for its own entry points.
const Challenge: React.FC = () => {
  const navigate = useNavigate();
  const {
    navitars,
    userNavitar,
    businessNavitars,
    addVenueOpponent,
    addWildOpponent,
    addRemoteOpponent,
  } = useNavitarFightClub();
  const { setPendingChallenge } = useVenue();
  const { user } = useAuth();
  const { networkingStatus, visibility } = usePresence();

  // The handoff is read once on mount: it names a moment (who you
  // just met), not a live feed — re-reading it mid-screen could swap
  // the pairing under the player if another tab wrote a new one.
  const [handoff] = useState<ChallengeHandoff | null>(() => loadChallengeHandoff());
  // The opponent record id as resolved in the pool. Normally the
  // handoff's own id; after a post-reload rebuild it is whatever the
  // adder returned (the adders derive stable ids, so they agree —
  // this state just keeps the screen honest if they ever don't).
  const [resolvedId, setResolvedId] = useState<string | null>(handoff?.opponentId ?? null);
  const rebuildAttemptedFor = useRef<string | null>(null);

  // The opponent pool is in-memory only: if a reload (or a fresh
  // tab) dropped the record, rebuild it from the handoff's fighter
  // data. Attempted once per handoff — if the adder refuses (a
  // locked design can never be an opponent), the screen says so
  // instead of spinning forever.
  useEffect(() => {
    if (!handoff || !resolvedId) return;
    if (businessNavitars.some(n => n.id === resolvedId)) return;
    const attemptKey = `${handoff.opponentId}|${handoff.ts}`;
    if (rebuildAttemptedFor.current === attemptKey) return;
    rebuildAttemptedFor.current = attemptKey;
    const input = handoff.opponent;
    const id =
      handoff.kind === 'wild'
        ? addWildOpponent(input)
        : handoff.kind === 'remote'
          ? addRemoteOpponent(input, handoff.opponentId)
          : addVenueOpponent(input);
    if (id) setResolvedId(id);
  }, [handoff, resolvedId, businessNavitars, addVenueOpponent, addWildOpponent, addRemoteOpponent]);

  const opponent = resolvedId ? (businessNavitars.find(n => n.id === resolvedId) ?? null) : null;
  const rebuildRefused = !!handoff && !opponent && rebuildAttemptedFor.current !== null;

  // Round 33: this screen is the approval surface, so the fight's
  // REALM is resolved and shown HERE, before Battle is pressed.
  // A venue/event challenge runs in that place's FIXED realm by
  // default; the player can switch this fight to a random roll
  // with the toggle below (the roll happens the moment they switch,
  // so what they see is what the duel runs). A non-venue challenge
  // is random by rule — rolled once when the screen first resolves
  // it, then persisted on the handoff so a reload or the Navidex
  // swap detour never silently re-rolls the approved realm.
  const fixedRealm: Element | null = handoff?.venueId ? venueRealmElement(handoff.venueId) : null;
  const [realmChoice, setRealmChoice] = useState<DuelRealm | null>(() => {
    if (!handoff) return null;
    if (handoff.realmElement) {
      return {
        element: handoff.realmElement as Element,
        source: handoff.realmSource ?? 'random',
        venueName: handoff.venueName,
      };
    }
    if (fixedRealm) {
      return { element: fixedRealm, source: 'fixed', venueName: handoff.venueName };
    }
    return { element: rollRealmElement(), source: 'random' };
  });
  // Persist a freshly resolved realm (a first roll, or a toggle)
  // onto the handoff: the swap detour and any reload keep the SAME
  // realm the player approved, and startBattle re-saves it with the
  // directStart flag for NavitarBattle to consume.
  useEffect(() => {
    if (!handoff || !realmChoice) return;
    if (
      handoff.realmElement === realmChoice.element &&
      handoff.realmSource === realmChoice.source
    ) {
      return;
    }
    saveChallengeHandoff({
      ...handoff,
      realmElement: realmChoice.element,
      realmSource: realmChoice.source,
    });
    // The handoff snapshot is mount-time by design (see above); the
    // realm is the one field this screen owns and keeps current.
  }, [realmChoice]);
  const toggleRealmRandom = (toRandom: boolean) => {
    if (!handoff) return;
    if (toRandom) {
      setRealmChoice({
        element: rollRealmElement(),
        source: 'random',
        venueName: handoff.venueName,
      });
    } else if (fixedRealm) {
      setRealmChoice({ element: fixedRealm, source: 'fixed', venueName: handoff.venueName });
    }
  };

  // 3D honesty (Round 8's one test, shared with Battle Step 1/2):
  // a fighter with no model — its own or a showcase twin's — stands
  // in the arena as its portrait. Said here, on the pairing, before
  // anyone presses Battle.
  const opponentHasModel = opponent ? !!resolveShowcaseModel(opponent, businessNavitars) : false;
  const playerHasModel = userNavitar
    ? !!resolveShowcaseModel(userNavitar, businessNavitars)
    : false;
  // Mirror matches read as one fighter fighting itself without the
  // duel convention (NavitarBattle's duelNames): yours is "Your X".
  const playerDisplayName =
    userNavitar && opponent && opponent.name === userNavitar.name
      ? `Your ${userNavitar.name}`
      : (userNavitar?.name ?? null);

  const startBattle = () => {
    if (!handoff || !opponent || !userNavitar) return;
    // P2.2a: a REAL challenge completes HERE — the moment the player
    // takes the duel up. Paste #2's guard allows accepted→completed
    // for both the recipient and the sender; the status filter makes
    // it a clean no-op if the other side already completed the row
    // (or it was declined meanwhile). Best effort and fire-and-forget:
    // a failed mark must never block the duel the player approved.
    if (handoff.challengeId) {
      void supabase
        .from('challenges')
        .update({ status: 'completed' })
        .eq('id', handoff.challengeId)
        .eq('status', 'accepted')
        .then(
          () => undefined,
          () => undefined
        );
    }
    // The Battle page's existing plumbing (pre-selected opponent +
    // venue bookkeeping), plus the directStart flag that makes this
    // screen the one approval: the duel starts on arrival.
    setPendingChallenge(opponent.id, handoff.venueId);
    saveChallengeHandoff({
      ...handoff,
      opponentId: opponent.id,
      directStart: true,
      // Round 33: the realm approved on this screen rides along —
      // the duel runs in exactly this realm.
      realmElement: realmChoice?.element,
      realmSource: realmChoice?.source,
    });
    navigate('/battle');
  };

  // ---- P2.2b: the LIVE door --------------------------------------
  // A real challenge (a server row, not a demo pairing) can be
  // fought live, phone to phone, when the friend is actually in
  // the game right now — their real presence (utils/friendPresence)
  // is what lights this door. The friend behind a remote pairing is
  // the user id inside the `friend-<userId>` opponent id.
  const liveFriendId =
    handoff?.kind === 'remote' && handoff.opponentId.startsWith('friend-')
      ? handoff.opponentId.slice('friend-'.length)
      : null;
  const livePresence = useFriendPresence(
    user?.id ?? null,
    networkingStatus,
    visibility,
    liveFriendId && handoff?.challengeId ? [liveFriendId] : []
  );
  const friendPresent = liveFriendId ? livePresence.has(liveFriendId) : false;
  // The live door also needs the battle_sessions table to answer:
  // until Paste #4 lands every probe fails (PGRST205) and the door
  // simply never renders — snapshot duels carry on exactly as
  // P2.2a left them. The probe doubles as the existing-session
  // lookup (both players pressing Battle live at once rendezvous
  // on the one row per challenge).
  const [liveSession, setLiveSession] = useState<BattleSessionRow | null>(null);
  const [liveAvailable, setLiveAvailable] = useState(false);
  const [liveBusy, setLiveBusy] = useState(false);
  const [liveError, setLiveError] = useState<string | null>(null);
  useEffect(() => {
    if (!handoff?.challengeId || !user || handoff.demo) return;
    let stopped = false;
    void fetchSessionForChallenge(handoff.challengeId)
      .then(row => {
        if (stopped) return;
        setLiveAvailable(true);
        setLiveSession(row);
      })
      .catch(() => {
        if (!stopped) setLiveAvailable(false);
      });
    return () => {
      stopped = true;
    };
  }, [handoff?.challengeId, handoff?.demo, user]);

  const startLiveBattle = async () => {
    if (!handoff || !opponent || !userNavitar || !user || !liveFriendId || !handoff.challengeId)
      return;
    setLiveBusy(true);
    setLiveError(null);
    try {
      // The challenge row itself names the roles (challenger =
      // from_user, challenged = to_user) — read it fresh rather
      // than guessing from which surface handed me here.
      const { data: challengeData, error: challengeError } = await supabase
        .from('challenges')
        .select('id, from_user, to_user, from_navitar, status')
        .eq('id', handoff.challengeId)
        .single();
      if (challengeError) throw challengeError;
      const challenge = challengeData as {
        from_user: string;
        to_user: string;
        from_navitar: NavitarSnapshot;
        status: string;
      };
      const opponentSnapshot: NavitarSnapshot = {
        name: handoff.opponent.name,
        element: handoff.opponent.element,
        level: handoff.opponent.level,
        skills: handoff.opponent.skills,
        imageUrl: handoff.opponent.imageUrl,
        modelUrl: handoff.opponent.modelUrl,
        modelZoom: handoff.opponent.modelZoom,
      };
      const iAmChallenger = challenge.from_user === user.id;
      // The session's agreed fighters: MINE is my CURRENT fighter
      // (a swap on this screen counts, whichever side I'm on);
      // THEIRS is the snapshot this pairing already stands on —
      // the challenge row's committed fighter when they challenged
      // me, their standing profile snapshot when I challenged them.
      const challengerSnapshot = iAmChallenger
        ? navitarSnapshot(userNavitar)
        : challenge.from_navitar;
      const challengedSnapshot = iAmChallenger ? opponentSnapshot : navitarSnapshot(userNavitar);

      let session = liveSession;
      if (session && (session.status === 'completed' || session.status === 'void')) {
        setLiveError('That live battle is already over — the snapshot duel below still works.');
        return;
      }
      if (!session) {
        try {
          session = await createBattleSession({
            challengeId: handoff.challengeId,
            challengerId: challenge.from_user,
            challengedId: challenge.to_user,
            challengerSnapshot,
            challengedSnapshot,
            creatorId: user.id,
          });
        } catch (err) {
          // 23505: the one-session-per-challenge index — the other
          // player pressed Battle live at the same moment. Fetch
          // their session and join it instead of failing.
          const code = (err as { code?: string })?.code;
          if (code !== '23505') throw err;
          session = await fetchSessionForChallenge(handoff.challengeId);
          if (!session) throw err;
        }
      }
      if (session.status === 'forming' && session.created_by !== user.id) {
        // I'm the second one here: my press IS the join.
        await joinBattleSession(session.id);
        session = { ...session, status: 'live' };
      }
      // Taking the duel up completes the challenge row, exactly as
      // the snapshot door does (P2.2a semantics, guard-legal for
      // both parties, a no-op if already completed).
      void supabase
        .from('challenges')
        .update({ status: 'completed' })
        .eq('id', handoff.challengeId)
        .eq('status', 'accepted')
        .then(
          () => undefined,
          () => undefined
        );
      setPendingChallenge(opponent.id, handoff.venueId);
      saveChallengeHandoff({
        ...handoff,
        opponentId: opponent.id,
        directStart: true,
        liveSessionId: session.id,
        realmElement: realmChoice?.element,
        realmSource: realmChoice?.source,
      });
      navigate('/battle');
    } catch (err) {
      setLiveError(
        `Could not start the live battle (${err instanceof Error ? err.message : 'network error'}). The snapshot duel below still works.`
      );
    } finally {
      setLiveBusy(false);
    }
  };

  if (!handoff) {
    return (
      <Container maxWidth="sm" sx={{ py: 4 }} data-testid="challenge-page">
        <Paper sx={{ p: 3, textAlign: 'center' }} data-testid="challenge-empty">
          <Typography variant="h5" gutterBottom>
            ⚔️ No challenge waiting
          </Typography>
          <Typography variant="body1" color="text.secondary" paragraph>
            Challenges start where you meet people — check in on the World Map, open Networking, or
            pick a friend. When you choose to battle someone, their matchup lands here, already
            paired with your fighter.
          </Typography>
          <Box sx={{ display: 'flex', gap: 1, justifyContent: 'center', flexWrap: 'wrap' }}>
            <Button component={RouterLink} to="/map" variant="contained">
              World Map
            </Button>
            <Button component={RouterLink} to="/networking" variant="outlined">
              Networking
            </Button>
            <Button component={RouterLink} to="/friends" variant="outlined">
              Friends
            </Button>
            <Button component={RouterLink} to="/battle" variant="outlined">
              Battle Arena
            </Button>
          </Box>
        </Paper>
      </Container>
    );
  }

  const fighterBox = (
    side: 'you' | 'them',
    name: string | null,
    sub: string,
    art: string | null | undefined,
    element: string
  ) => (
    <Box
      sx={{
        flex: '1 1 130px',
        textAlign: 'center',
        p: 1.5,
        borderRadius: 3,
        bgcolor: 'rgba(255,255,255,0.04)',
        border: '1px solid rgba(120, 200, 225, 0.16)',
      }}
    >
      <Typography variant="caption" color="text.secondary" sx={{ letterSpacing: '0.08em' }}>
        {side === 'you' ? 'YOU' : 'OPPONENT'}
      </Typography>
      <Box sx={{ display: 'flex', justifyContent: 'center', my: 1 }}>
        <NavitarArtImg
          src={art ?? ''}
          alt={`${name ?? 'Fighter'} art`}
          element={element}
          fit="contain"
          style={{ width: 110, height: 110, borderRadius: 16, objectFit: 'contain' }}
        />
      </Box>
      <Typography variant="subtitle1" sx={{ fontWeight: 800, lineHeight: 1.2 }}>
        {elementEmoji(element)} {name ?? '—'}
      </Typography>
      <Typography variant="body2" color="text.secondary">
        {sub}
      </Typography>
    </Box>
  );

  return (
    <Container maxWidth="sm" sx={{ py: 4 }} data-testid="challenge-page">
      <Typography variant="h4" gutterBottom align="center">
        ⚔️ Battle challenge
      </Typography>
      <Typography
        variant="body1"
        color="text.secondary"
        align="center"
        sx={{ mb: 3 }}
        data-testid="challenge-intro"
      >
        {handoff.personName
          ? `You met ${handoff.personName}${handoff.venueName ? ` at ${handoff.venueName}` : ''}. This is the matchup — swap your fighter if you like, then battle.`
          : `A wild ${handoff.opponent.name} blocks your path. This is the matchup — swap your fighter if you like, then battle.`}
      </Typography>

      <Paper sx={{ p: 2.5, mb: 3 }}>
        <Box
          sx={{ display: 'flex', gap: 1.5, alignItems: 'stretch', flexWrap: 'wrap' }}
          data-testid="challenge-pairing"
        >
          {fighterBox(
            'you',
            playerDisplayName,
            userNavitar
              ? `Lv. ${userNavitar.level} · ${userNavitar.element}`
              : 'No fighter chosen yet',
            userNavitar ? resolveNavitarArt(userNavitar.imageUrl, userNavitar.name) : null,
            userNavitar?.element ?? 'ice'
          )}
          <Box
            sx={{
              alignSelf: 'center',
              mx: 'auto',
              width: 44,
              height: 44,
              borderRadius: '50%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              fontWeight: 900,
              bgcolor: '#e8912d',
              color: '#081a24',
              flexShrink: 0,
            }}
          >
            VS
          </Box>
          {fighterBox(
            'them',
            opponent?.name ?? handoff.opponent.name,
            opponent
              ? `Lv. ${opponent.level} · ${opponent.element}`
              : `Lv. ${handoff.opponent.level} · ${handoff.opponent.element}`,
            opponent
              ? (opponent.imageUrl ?? resolveNavitarArt(undefined, opponent.name))
              : (handoff.opponent.imageUrl ?? resolveNavitarArt(undefined, handoff.opponent.name)),
            opponent?.element ?? handoff.opponent.element
          )}
        </Box>

        {handoff.personName && (
          <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 2 }}>
            {handoff.personName} fields {opponent?.name ?? handoff.opponent.name} — you field{' '}
            {playerDisplayName ?? 'your chosen fighter'}.
          </Typography>
        )}
        {opponent && !opponentHasModel && (
          <Typography
            variant="body2"
            color="text.secondary"
            align="center"
            sx={{ mt: 1 }}
            data-testid="challenge-opponent-no-model"
          >
            {opponent.name} has no 3D model yet — it will stand in the arena as its portrait.
          </Typography>
        )}
        {userNavitar && !playerHasModel && (
          <Typography
            variant="body2"
            color="text.secondary"
            align="center"
            sx={{ mt: 1 }}
            data-testid="challenge-player-no-model"
          >
            {userNavitar.name} has no 3D model yet — in the arena it will fight as its portrait.
            Swap in the Navidex to a fighter that stands there in <strong>3D</strong> to battle in
            full 3D.
          </Typography>
        )}
        <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 1 }}>
          {handoff.demo
            ? 'Demo person — met on this device; the duel plays out here and banks like every duel.'
            : 'Your friend’s navitar, dueled here — points and XP bank on this device, like every duel.'}
        </Typography>
      </Paper>

      {/* Round 33: the realm this fight runs in — resolved on this
          approval surface and stated plainly, with its effect. A
          venue/event fight is fixed to the place's realm unless
          the player switches this fight to a random roll. */}
      {realmChoice && (
        <Paper sx={{ p: 2.5, mb: 3 }} data-testid="challenge-realm">
          <Typography
            variant="body1"
            align="center"
            sx={{ fontWeight: 700 }}
            data-testid="challenge-realm-line"
          >
            {realmStageLine(realmChoice.element)}
          </Typography>
          <Typography variant="body2" color="text.secondary" align="center" sx={{ mt: 1 }}>
            {realmChoice.source === 'fixed'
              ? `This fight's realm is fixed by ${handoff.venueName ?? 'the venue'} — fights at this place run in its realm.`
              : 'This fight’s realm was rolled at random — neither side picked it.'}
          </Typography>
          {fixedRealm && (
            <Box
              sx={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                gap: 1,
                mt: 1.5,
              }}
            >
              <Switch
                checked={realmChoice.source === 'random'}
                onChange={e => toggleRealmRandom(e.target.checked)}
                inputProps={{ 'aria-label': 'Roll a random realm instead' }}
                data-testid="challenge-realm-toggle"
              />
              <Typography variant="body2">🎲 Roll a random realm instead</Typography>
            </Box>
          )}
        </Paper>
      )}

      {rebuildRefused ? (
        <Paper sx={{ p: 3, mb: 3, textAlign: 'center' }} data-testid="challenge-refused">
          <Typography variant="body1" paragraph>
            {handoff.opponent.name} can’t be fielded as an opponent right now, so this challenge
            can’t go ahead.
          </Typography>
          <Button variant="contained" onClick={() => navigate(handoff.returnTo)}>
            ← Back to {handoff.sourceLabel}
          </Button>
        </Paper>
      ) : !userNavitar ? (
        <Paper
          sx={{ p: 3, mb: 3, textAlign: 'center', border: '1px solid', borderColor: '#e8912d' }}
          data-testid="challenge-no-fighter"
        >
          <Typography variant="h6" gutterBottom>
            Choose your fighter
          </Typography>
          <Typography variant="body1" color="text.secondary" paragraph>
            {navitars.length === 0
              ? // Round 16: the Navidex choose is owned-only, so a
                // player with NO navitars is sent to the real
                // on-ramp — Home, where adoption/creation live —
                // not to a roster page that can only show locks.
                'You have no navitars yet. Adopt or create one on the Home page — this challenge stays saved here, and the pairing will be waiting when you come back.'
              : 'Pick the navitar that fights for you in the Navidex — this challenge is saved, and the pairing will be right here when you come back.'}
          </Typography>
          <Box data-testid="challenge-choose">
            {navitars.length === 0 ? (
              <Button
                component={RouterLink}
                to="/"
                variant="contained"
                size="large"
                sx={{ fontWeight: 'bold' }}
              >
                Adopt or create your fighter
              </Button>
            ) : (
              <NavidexSwapButton
                label="Choose your fighter"
                variant="contained"
                returnTo="/challenge"
                contextLabel={`your battle with ${handoff.opponent.name}`}
              />
            )}
          </Box>
        </Paper>
      ) : (
        <Box
          sx={{
            display: 'flex',
            gap: 1.5,
            justifyContent: 'center',
            flexWrap: 'wrap',
            mb: 3,
          }}
        >
          {/* P2.2b: the LIVE door — a real challenge, the friend
              present right now, and the sessions table answering.
              Pressing it creates (or joins) the battle session and
              hands the pairing to the arena as a live duel. */}
          {!handoff.demo && handoff.challengeId && liveAvailable && friendPresent && (
            <Box sx={{ flexBasis: '100%', textAlign: 'center' }}>
              <Button
                variant="contained"
                color="secondary"
                size="large"
                disabled={!opponent || liveBusy}
                onClick={() => void startLiveBattle()}
                data-testid="challenge-battle-live"
                sx={{ px: 4, py: 1.5, fontSize: '1.1rem', fontWeight: 'bold' }}
              >
                🔴 Battle LIVE — {handoff.personName ?? 'your friend'} is here now
              </Button>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                A live battle runs on both phones at once — you pick your moves, they pick theirs.
              </Typography>
            </Box>
          )}
          {!handoff.demo && handoff.challengeId && liveAvailable && !friendPresent && (
            <Typography
              variant="body2"
              color="text.secondary"
              align="center"
              sx={{ flexBasis: '100%' }}
              data-testid="challenge-live-absent"
            >
              Battle LIVE unlocks when {handoff.personName ?? 'your friend'} is in the game — right
              now, ⚔️ Battle below fights their navitar here.
            </Typography>
          )}
          {liveError && (
            <Typography
              variant="body2"
              color="error"
              align="center"
              sx={{ flexBasis: '100%' }}
              data-testid="challenge-live-error"
            >
              {liveError}
            </Typography>
          )}
          <Button
            variant="contained"
            color="primary"
            size="large"
            disabled={!opponent}
            onClick={startBattle}
            data-testid="challenge-battle"
            sx={{ px: 4, py: 1.5, fontSize: '1.1rem', fontWeight: 'bold' }}
          >
            ⚔️ Battle
          </Button>
          <Box data-testid="challenge-swap">
            <NavidexSwapButton
              label="🔄 Swap fighter"
              size="large"
              variant="outlined"
              returnTo="/challenge"
              contextLabel={`your battle with ${handoff.opponent.name}`}
            />
          </Box>
        </Box>
      )}

      <Box sx={{ textAlign: 'center' }}>
        <Button onClick={() => navigate(handoff.returnTo)} data-testid="challenge-back">
          ← Back to {handoff.sourceLabel}
        </Button>
      </Box>
    </Container>
  );
};

export default Challenge;
