// Real-request producer (P2.1b) — the real counterpart of
// IncomingRequestProducer. Headless, like the other producers: it
// polls the REAL friends / challenges tables for the signed-in
// player and announces what is new — an incoming friend request,
// an incoming challenge invite, a sent challenge the other side
// accepted — through the one notifications store. It renders
// nothing.
//
// Discipline (the demo producer's shape + the Round 22 law):
// - TYPE-ONLY records: the title is the type plus the sender
//   ("🤝 Friend request from @name") and the body is a generic
//   pointer to Profile, where the real-friends section lives.
//   Nothing else rides in the record or the toast — no navitar
//   details, no message text, nothing about location.
// - These records are REAL (demo: false) and are never framed as
//   demo anywhere. The demo producer's records keep their demo
//   framing; the two sources sit side by side in one list.
// - The record id is stable per table row and the store dedupes
//   by id, so each request is announced exactly once per device,
//   however long it sits pending.
// - It waits for a quiet moment: the player is not standing on
//   /profile (they'd see the section itself) and no other toast
//   is up — news doesn't pile on news. One announcement per poll
//   tick, oldest first.
// - Poll cadence matches Profile's own refresh (30s); ticks
//   suspend while the app is idle-asleep. Signed-out there is
//   nothing to poll; a failed fetch is swallowed and retried on
//   the next tick — this producer never shows an error.
import React, { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import { useNotifications } from '../contexts/NotificationsContext';
import { loadNotifications, type NotificationInput } from '../utils/notifications';
import { isAppIdle } from '../utils/idleSleep';
import {
  fetchIncomingChallenges,
  fetchIncomingRequests,
  fetchProfilesByIds,
  fetchSentChallenges,
  type ProfileRow,
} from '../utils/onlineFriends';
import { fetchWaitingSessions } from '../utils/battleSession';

const FIRST_CHECK_MS = 6000;
const POLL_MS = 30000;

export function realFriendRequestNotificationId(rowId: string): string {
  return `friend-request-real-${rowId}`;
}

export function realChallengeInviteNotificationId(rowId: string): string {
  return `challenge-invite-real-${rowId}`;
}

export function realChallengeAcceptedNotificationId(rowId: string): string {
  return `challenge-accepted-real-${rowId}`;
}

// P2.2b: a friend is standing in the arena waiting for me to join
// their live battle (a battle_sessions row in 'forming', created
// by them). Announced once per session; the Battle page's join
// card is the approval surface the tap lands on.
export function liveBattleInviteNotificationId(sessionId: string): string {
  return `live-battle-invite-${sessionId}`;
}

// The sender as a notification may name them: their @name when
// they have claimed one, else their display name. Type-only law —
// this is the ONLY thing about the sender that rides along.
function senderLabel(profile: ProfileRow | null): string {
  if (profile?.username) return `@${profile.username}`;
  return profile?.display_name ?? 'A player';
}

const RealRequestProducer: React.FC = () => {
  const { user } = useAuth();
  const { notify, toasts } = useNotifications();
  const location = useLocation();
  const toastsRef = useRef(toasts);
  toastsRef.current = toasts;
  const pathRef = useRef(location.pathname);
  pathRef.current = location.pathname;
  const userId = user?.id ?? null;

  useEffect(() => {
    if (!userId) return;
    let stopped = false;
    let poll: number | null = null;

    const attempt = async () => {
      if (stopped) return;
      // Producers suspend while the app sleeps; the next tick
      // after a wake decides afresh.
      if (isAppIdle()) return;
      let owed: NotificationInput[] = [];
      try {
        const [requests, invites, sent] = await Promise.all([
          fetchIncomingRequests(userId),
          fetchIncomingChallenges(userId),
          fetchSentChallenges(userId),
        ]);
        // Live-battle invites ride their own fetch: until Paste #4
        // lands the sessions table doesn't answer, and that failure
        // must not silence the friends/challenges announcements.
        let liveInvites: NotificationInput[] = [];
        try {
          const waiting = await fetchWaitingSessions(userId);
          const fresh = waiting.filter(
            s => !loadNotifications().some(r => r.id === liveBattleInviteNotificationId(s.id))
          );
          if (fresh.length > 0) {
            const creators = await fetchProfilesByIds(fresh.map(s => s.created_by));
            const byId = new Map(creators.map(p => [p.id, p]));
            liveInvites = fresh.map((s): NotificationInput => ({
              id: liveBattleInviteNotificationId(s.id),
              kind: 'friend',
              title: `⚔️ ${senderLabel(byId.get(s.created_by) ?? null)} is waiting to battle you LIVE`,
              body: 'Tap to open the Battle page and join the live battle',
              route: '/battle',
              demo: false,
            }));
          }
        } catch {
          // Sessions table not live yet — no invites to announce.
        }
        const stored = new Set(loadNotifications().map(r => r.id));
        owed = [
          // A live invite is time-sensitive (someone is standing
          // in the arena waiting), so it announces ahead of the
          // standing requests on the next quiet tick.
          ...liveInvites,
          ...requests
            .filter(e => !stored.has(realFriendRequestNotificationId(e.row.id)))
            .map((e): NotificationInput => ({
              id: realFriendRequestNotificationId(e.row.id),
              kind: 'friend',
              title: `🤝 Friend request from ${senderLabel(e.profile)}`,
              body: 'Tap to open your Profile and answer it',
              route: '/profile',
              demo: false,
            })),
          ...invites
            .filter(e => !stored.has(realChallengeInviteNotificationId(e.row.id)))
            .map((e): NotificationInput => ({
              id: realChallengeInviteNotificationId(e.row.id),
              kind: 'friend',
              title: `⚔️ Challenge from ${senderLabel(e.profile)}`,
              body: 'Tap to open your Profile and see the challenge',
              route: '/profile',
              demo: false,
            })),
          ...sent
            .filter(
              e =>
                e.row.status === 'accepted' &&
                !stored.has(realChallengeAcceptedNotificationId(e.row.id))
            )
            .map((e): NotificationInput => ({
              id: realChallengeAcceptedNotificationId(e.row.id),
              kind: 'friend',
              title: `⚔️ ${senderLabel(e.profile)} accepted your challenge`,
              body: 'Tap to open your Profile and take the battle',
              route: '/profile',
              demo: false,
            })),
        ];
      } catch {
        // Offline, or a table is missing: say nothing, try the
        // next tick. This producer never surfaces an error.
        return;
      }
      if (stopped || owed.length === 0) return;
      // Not while the player is standing on Profile (the section
      // itself is in front of them — the record is created on a
      // later tick if the row is still pending), and not on top
      // of another pop-up.
      if (pathRef.current.startsWith('/profile')) return;
      if (toastsRef.current.length > 0) return;
      notify(owed[0]);
    };

    const first = window.setTimeout(() => {
      void attempt();
      poll = window.setInterval(() => {
        void attempt();
      }, POLL_MS);
    }, FIRST_CHECK_MS);
    return () => {
      stopped = true;
      window.clearTimeout(first);
      if (poll !== null) window.clearInterval(poll);
    };
  }, [notify, userId]);

  return null;
};

export default RealRequestProducer;
