import React, { useState } from 'react';
import { Box, Button, Container, MenuItem, Paper, TextField, Typography } from '@mui/material';
import { GLOW_THEME_LIST, type GlowThemeId } from '../data/venueBuzz';
import { US_STATES, submitVenueApplication } from '../utils/venueApplications';

// For Venues — the Pilot Host application (Modern View integration,
// Eddie 2026-11-16). A business says "we want to advertise on your
// platform / host battles" here: join the Southern California Pilot
// Corridor as a founding GLACER venue — listed on the World Map as a
// perk venue, host of navitar battles, promoted to players nearby.
//
// SAVING (Round 37-V, Eddie's launch gate 2026-11-20): the form
// writes to the public.venue_applications table in GLACER's
// Supabase project (see src/utils/venueApplications.ts), where the
// application is saved and Eddie reviews it personally from his
// admin window. The table is created by one pasted SQL migration;
// until that has run, the write comes back "not configured" and
// this form says so PLAINLY — no fake save. Either way the venue
// gets a reference code, and a copy stays on this device
// (localStorage) as their own record.
export const VENUE_APPLICATIONS_KEY = 'glacer-venue-applications';

interface VenueApplication {
  ref: string;
  venueName: string;
  venueType: string;
  city: string;
  state: string;
  contactName: string;
  email: string;
  phone: string;
  social: string;
  bestNight: string;
  perkIdea: string;
  glowTheme: GlowThemeId;
  notes: string;
  submittedAt: string;
}

const VENUE_TYPES = [
  'Bar',
  'Brewery / Taproom',
  'Lounge',
  'Café',
  'Restaurant',
  'Arcade / Gaming',
  'Other',
];
const NIGHTS = ['Thursday', 'Friday', 'Saturday', 'Sunday', 'Weeknight — let’s talk'];

const empty = {
  venueName: '',
  venueType: 'Bar',
  city: '',
  state: 'CA',
  contactName: '',
  email: '',
  phone: '',
  social: '',
  bestNight: 'Friday',
  perkIdea: '',
  glowTheme: 'fire' as GlowThemeId,
  notes: '',
};

const VenueJoin: React.FC = () => {
  const [form, setForm] = useState(empty);
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);
  const [submitted, setSubmitted] = useState<VenueApplication | null>(null);
  const [unsaved, setUnsaved] = useState<{
    app: VenueApplication;
    reason: 'not_configured' | 'failed';
  } | null>(null);

  const set = (k: keyof typeof empty) => (e: React.ChangeEvent<HTMLInputElement>) =>
    setForm(prev => ({ ...prev, [k]: e.target.value }));

  const submit = async () => {
    if (!form.venueName.trim() || !form.city.trim() || !form.contactName.trim()) {
      setError('Venue name, city, and a contact name are the minimum we need to start.');
      return;
    }
    if (!/^\S+@\S+\.\S+$/.test(form.email.trim())) {
      setError('A valid contact email is required so the GLACER team can reach you.');
      return;
    }
    setError(null);
    setSaving(true);
    const app: VenueApplication = {
      ...form,
      ref: `GLV-${Date.now().toString(36).toUpperCase()}`,
      submittedAt: new Date().toISOString(),
    };
    // The venue's own on-device copy — kept in every outcome, so
    // their answers are never lost even when the save can't land.
    try {
      const raw = localStorage.getItem(VENUE_APPLICATIONS_KEY);
      const list: VenueApplication[] = raw ? JSON.parse(raw) : [];
      list.push(app);
      localStorage.setItem(VENUE_APPLICATIONS_KEY, JSON.stringify(list));
    } catch {
      // Storage unavailable — the reference screen still shows so the
      // venue can quote it; nothing is silently lost from their view.
    }
    const result = await submitVenueApplication(app);
    setSaving(false);
    if (result.kind === 'saved') {
      setSubmitted(app);
    } else {
      // NEVER fake-save: the form says plainly that GLACER has not
      // received this yet, and the filled form stays one tap away
      // with every answer intact.
      setUnsaved({ app, reason: result.kind });
    }
  };

  if (unsaved) {
    return (
      <Container maxWidth="sm" sx={{ py: 5 }}>
        <Paper sx={{ p: 4, textAlign: 'center' }}>
          <Typography variant="h4" gutterBottom>
            ⚠️ Not saved yet — please read
          </Typography>
          <Typography variant="body1" paragraph>
            Your application for <strong>{unsaved.app.venueName}</strong> has{' '}
            <strong>not reached GLACER yet</strong>.{' '}
            {unsaved.reason === 'not_configured'
              ? 'The venue inbox is not switched on in this build, so there is nowhere for it to save to right now.'
              : 'The save did not go through — a connection problem, not anything wrong with your answers.'}
          </Typography>
          <Typography variant="body1" paragraph>
            Your reference code: <strong>{unsaved.app.ref}</strong>
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            Your answers are kept on this device only, and your filled form is untouched — nothing
            you typed is lost. To reach the team today, email <strong>glacerhq@gmail.com</strong>{' '}
            with the words “Glacer Venue” and your reference code, or come back and send the form
            again once the inbox is on.
          </Typography>
          <Button variant="contained" onClick={() => setUnsaved(null)}>
            Back to your application
          </Button>
        </Paper>
      </Container>
    );
  }

  if (submitted) {
    return (
      <Container maxWidth="sm" sx={{ py: 5 }}>
        <Paper sx={{ p: 4, textAlign: 'center' }}>
          <Typography variant="h4" gutterBottom>
            🎉 Application saved
          </Typography>
          <Typography variant="body1" paragraph>
            <strong>{submitted.venueName}</strong> is in line for the Southern California Pilot
            Corridor — a founding host of GLACER navitar battles.
          </Typography>
          <Typography variant="body1" paragraph>
            Your reference code: <strong>{submitted.ref}</strong>
          </Typography>
          <Typography variant="body1" paragraph>
            Your map glow theme:{' '}
            <strong>
              {GLOW_THEME_LIST.find(t => t.id === submitted.glowTheme)?.emoji}{' '}
              {GLOW_THEME_LIST.find(t => t.id === submitted.glowTheme)?.name}
            </strong>{' '}
            — your pin glows like this whenever an event or promo is live.
          </Typography>
          <Typography variant="body2" color="text.secondary" paragraph>
            Your application is saved with GLACER. Pilot hosts are reviewed personally — Eddie reads
            every application himself — so keep your reference code handy; it identifies your saved
            application.
          </Typography>
          <Button
            variant="contained"
            onClick={() => {
              setSubmitted(null);
              setForm(empty);
            }}
          >
            Add another venue
          </Button>
        </Paper>
      </Container>
    );
  }

  return (
    <Container maxWidth="sm" sx={{ py: 5 }}>
      <Typography variant="h4" gutterBottom align="center">
        For Venues — Become a Pilot Host
      </Typography>
      <Typography variant="body1" color="text.secondary" align="center" paragraph>
        GLACER sends players into real places: they walk in for perks, meet people, and battle
        navitars — at your bar. Pilot hosts in Los Angeles and across Southern California get a
        World Map pin, a Suggested Venue listing, Battle Nights, and a perk they control.
      </Typography>
      <Paper sx={{ p: 3 }}>
        <Typography variant="h6" gutterBottom>
          Pilot Host application
        </Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          <TextField
            label="Venue name"
            value={form.venueName}
            onChange={set('venueName')}
            required
            fullWidth
          />
          <TextField
            label="Venue type"
            select
            value={form.venueType}
            onChange={set('venueType')}
            fullWidth
          >
            {VENUE_TYPES.map(t => (
              <MenuItem key={t} value={t}>
                {t}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            label="City / neighborhood"
            value={form.city}
            onChange={set('city')}
            required
            fullWidth
            placeholder="Van Nuys, Los Angeles"
          />
          <TextField label="State" select value={form.state} onChange={set('state')} fullWidth>
            {US_STATES.map(s => (
              <MenuItem key={s.code} value={s.code}>
                {s.name}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            label="Best night for a Battle Night"
            select
            value={form.bestNight}
            onChange={set('bestNight')}
            fullWidth
          >
            {NIGHTS.map(n => (
              <MenuItem key={n} value={n}>
                {n}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            label="Contact name"
            value={form.contactName}
            onChange={set('contactName')}
            required
            fullWidth
          />
          <TextField
            label="Contact email"
            type="email"
            value={form.email}
            onChange={set('email')}
            required
            fullWidth
          />
          <TextField
            label="Phone (optional)"
            value={form.phone}
            onChange={set('phone')}
            fullWidth
          />
          <TextField
            label="Website / social (optional)"
            value={form.social}
            onChange={set('social')}
            fullWidth
          />
          <TextField
            label="The perk you'd offer players"
            value={form.perkIdea}
            onChange={set('perkIdea')}
            fullWidth
            multiline
            minRows={2}
            placeholder="e.g. Show your GLACER check-in for 10% off your first round"
          />
          <TextField
            label="Map glow theme — how your venue glows on the map"
            select
            value={form.glowTheme}
            onChange={set('glowTheme')}
            fullWidth
            helperText="When your venue has a live event or promo, your map pin glows in the theme you pick here."
          >
            {GLOW_THEME_LIST.map(t => (
              <MenuItem key={t.id} value={t.id}>
                {t.emoji} {t.name}
              </MenuItem>
            ))}
          </TextField>
          <TextField
            label="Anything else (optional)"
            value={form.notes}
            onChange={set('notes')}
            fullWidth
            multiline
            minRows={2}
          />
          {error && (
            <Typography variant="body2" color="error">
              {error}
            </Typography>
          )}
          <Button variant="contained" size="large" onClick={submit} disabled={saving}>
            {saving ? 'Saving your application…' : 'Apply to host GLACER battles'}
          </Button>
          <Typography variant="body2" color="text.secondary">
            No invented terms: pilot pricing, perks, and scheduling are agreed personally with the
            GLACER team — nothing is promised or charged by this form.
          </Typography>
        </Box>
      </Paper>
    </Container>
  );
};

export default VenueJoin;
