import React, { useEffect, useState } from 'react';
import { Box, Typography } from '@mui/material';
import { getCare } from '../utils/training';
import { xpProgress } from '../utils/levels';

// Power tracker (Round 30, Eddie, 2026-11-18): a small status
// tracker that rides on the fighter — its level and an XP
// progress bar showing how powerful it is getting. The XP is
// the companion XP from the SAME source the Stage care panel
// reads (the glacer-stage-care-v1 care store, utils/training
// getCare) and the bar's fraction is the shared levels.ts curve
// (xpProgress) — no new numbers anywhere. A fighter with no
// care record reads its honest base state: its data level and
// an empty bar.
export const PowerTracker: React.FC<{
  name: string;
  level?: number;
  // The Stage passes its live care XP (its own state). Card
  // surfaces omit it and the tracker reads the care store
  // directly, re-reading whenever the store changes
  // (glacer-care-changed from updateCare, or a cross-tab
  // storage event) so a training session on the Stage is
  // reflected on the fighter's card below without a reload.
  xp?: number;
  // Dark-glass styling for the 3D stage's corner chip.
  dark?: boolean;
}> = ({ name, level, xp: xpProp, dark }) => {
  const [storedXp, setStoredXp] = useState<number>(() => getCare(name).xp);
  useEffect(() => {
    setStoredXp(getCare(name).xp);
  }, [name]);
  useEffect(() => {
    if (xpProp !== undefined) return;
    const reread = () => setStoredXp(getCare(name).xp);
    window.addEventListener('glacer-care-changed', reread);
    window.addEventListener('storage', reread);
    return () => {
      window.removeEventListener('glacer-care-changed', reread);
      window.removeEventListener('storage', reread);
    };
  }, [name, xpProp]);
  const xp = xpProp !== undefined ? xpProp : storedXp;
  const prog = xpProgress(xp);
  return (
    <Box
      data-power-tracker={name}
      data-xp-fraction={prog.fraction.toFixed(4)}
      sx={{ display: 'flex', alignItems: 'center', gap: 1, width: '100%' }}
    >
      {level !== undefined && (
        <Typography
          variant="caption"
          sx={{
            fontWeight: 900,
            whiteSpace: 'nowrap',
            color: dark ? '#eaf6fa' : 'text.primary',
          }}
        >
          Lv. {level}
        </Typography>
      )}
      <Box
        sx={{
          flex: 1,
          height: 6,
          borderRadius: 3,
          bgcolor: dark ? 'rgba(148,214,230,0.25)' : 'rgba(128,160,175,0.35)',
          overflow: 'hidden',
        }}
      >
        <Box
          data-xp-fill
          sx={{
            height: '100%',
            width: `${Math.round(prog.fraction * 1000) / 10}%`,
            borderRadius: 3,
            background: 'linear-gradient(90deg, #22a06b, #3ddc84)',
          }}
        />
      </Box>
      <Typography
        variant="caption"
        sx={{ whiteSpace: 'nowrap', color: dark ? '#cfeef8' : 'text.secondary' }}
      >
        XP {xp}
      </Typography>
    </Box>
  );
};
