// Sale listings — the shared sell flow (Round 19's Profile
// selling, Round 36.13 Part B: the DOOR moved to the Navidex).
//
// Round 19 put a Sell action on each owned fighter's card in
// Profile's "Your Navitars" grid. Eddie (2026-11-21 ~08:58 PT):
// the Profile grid goes entirely — "profile should be for your
// personal stuff, not the navitars" — and the sell option moves
// to the Navidex, on BOTH card surfaces (the Stage card and the
// deck front card). This module is the one sell flow behind both
// doors: the dialog below is Round 19's dialog verbatim (same
// words, same testids, same whole-dollar validation), and the
// listing store is the same utils/listings.ts store with the
// same `glacer-listings` key — listings created under the old
// Profile door keep working untouched, and they still surface
// where they always did (Profile's "Your listings").
//
// Ownership law (Round 16/19) is unchanged: only a fighter in
// the player's own collection can be listed. Resolution is by
// NAME through the FightClub collection — the same lookup the
// one choose path (useChooseNavitar) uses — so an unowned
// fighter renders no sell control at all, and Prime Zero is
// listable only where he can be owned (the owner collection).
import React from 'react';
import {
  Box,
  Button,
  Chip,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  TextField,
  Typography,
} from '@mui/material';
import { useNavitarFightClub } from '../contexts/NavitarFightClub';

type NavitarRecord = ReturnType<typeof useNavitarFightClub>['navitars'][number];
import {
  activeListingFor,
  loadListings,
  removeListing,
  saveListings,
  upsertListing,
  type NavitarListing,
} from '../utils/listings';
import { readLocalDisplayName } from '../utils/accountMerge';

// Listings state shared by every mounted sell surface (the Stage
// card and the deck front card sit on the same page): a write
// through this hook persists to the one store and broadcasts, so
// the other surface re-reads and both always show the same tag.
export const LISTINGS_CHANGED_EVENT = 'glacer-listings-changed';

export function useListings(): [NavitarListing[], (next: NavitarListing[]) => void] {
  const [listings, setListingsState] = React.useState<NavitarListing[]>(() => loadListings());
  React.useEffect(() => {
    const reload = () => setListingsState(loadListings());
    window.addEventListener(LISTINGS_CHANGED_EVENT, reload);
    return () => window.removeEventListener(LISTINGS_CHANGED_EVENT, reload);
  }, []);
  const setListings = React.useCallback((next: NavitarListing[]) => {
    saveListings(next);
    setListingsState(next);
    try {
      window.dispatchEvent(new Event(LISTINGS_CHANGED_EVENT));
    } catch {
      // No window event support: this surface's own state is already set.
    }
  }, []);
  return [listings, setListings];
}

/** The player's owned FightClub record for a fighter name, if any. */
export function useOwnedNavitarRecord(name: string): NavitarRecord | undefined {
  const { navitars } = useNavitarFightClub();
  return navitars.find(n => n.name === name);
}

// The Round 19 sell dialog, verbatim — the seller types their
// own whole-dollar price; the field starts empty on a fresh
// listing; nothing is pre-filled or suggested. Controlled: the
// caller owns target/price/error state and the confirm write.
export const SellNavitarDialog: React.FC<{
  target: { id: string; name: string } | null;
  price: string;
  error: string | null;
  onPriceChange: (value: string) => void;
  onConfirm: () => void;
  onClose: () => void;
}> = ({ target, price, error, onPriceChange, onConfirm, onClose }) => (
  <Dialog open={!!target} onClose={onClose} data-testid="sell-dialog" fullWidth maxWidth="xs">
    <DialogTitle>
      Sell {target?.name}{' '}
      <Chip label="DEMO" size="small" color="warning" sx={{ fontWeight: 'bold' }} />
    </DialogTitle>
    <DialogContent>
      <Typography variant="body2" color="text.secondary" paragraph>
        List {target?.name} for sale on your profile at your price. The listing lives on this device
        for now — a sale settles through the GLACER Wallet once payments are connected, and listing
        never changes who owns or can choose this navitar.
      </Typography>
      <TextField
        autoFocus
        fullWidth
        margin="dense"
        label="Price (USD)"
        type="number"
        placeholder="Your price — e.g. 250"
        value={price}
        onChange={e => onPriceChange(e.target.value)}
        inputProps={{ min: 1, step: 1, 'data-testid': 'sell-price-input' }}
        onKeyDown={e => {
          if (e.key === 'Enter') onConfirm();
        }}
      />
      {error && (
        <Typography variant="body2" color="error" sx={{ mt: 1 }}>
          {error}
        </Typography>
      )}
    </DialogContent>
    <DialogActions>
      <Button onClick={onClose}>Cancel</Button>
      <Button variant="contained" onClick={onConfirm} data-testid="sell-confirm-button">
        List for sale
      </Button>
    </DialogActions>
  </Dialog>
);

// The sell control for one fighter, by name — the Navidex door
// (Round 36.13 Part B). Mirrors the old Profile grid card's
// controls exactly: an unlisted owned fighter gets Sell; a
// listed one gets its FOR SALE tag plus Edit price / Unlist.
// An unowned fighter gets nothing (no door, no dead button).
export const NavitarSellAction: React.FC<{ name: string; testidPrefix: string }> = ({
  name,
  testidPrefix,
}) => {
  const owned = useOwnedNavitarRecord(name);
  const [listings, setListings] = useListings();
  const [target, setTarget] = React.useState<{ id: string; name: string } | null>(null);
  const [price, setPrice] = React.useState('');
  const [error, setError] = React.useState<string | null>(null);

  if (!owned) return null;
  const listing = activeListingFor(listings, owned.id);

  const openSell = () => {
    setTarget({ id: owned.id, name: owned.name });
    // A fresh listing starts EMPTY (no invented price); re-pricing
    // an existing listing starts from its current price.
    setPrice(listing ? String(listing.priceUSD) : '');
    setError(null);
  };

  const handleConfirmSell = () => {
    if (!target) return;
    const value = Number(price);
    if (!price.trim() || !Number.isFinite(value) || !Number.isInteger(value) || value <= 0) {
      setError('Enter a whole-dollar price above $0 — your price, your call.');
      return;
    }
    setListings(
      upsertListing(listings, {
        navitarId: target.id,
        navitarName: target.name,
        // The seller's label: the device display name (the same
        // local source Profile's label chain starts from), else
        // the plain fallback Profile used.
        sellerLabel: readLocalDisplayName() || 'You',
        priceUSD: value,
      })
    );
    setTarget(null);
    setPrice('');
    setError(null);
  };

  const handleUnlist = () => {
    setListings(removeListing(listings, owned.id));
  };

  return (
    <Box
      data-testid={`${testidPrefix}-sell-action`}
      data-navitar-id={owned.id}
      sx={{
        display: 'flex',
        gap: 1,
        flexWrap: 'wrap',
        alignItems: 'center',
        justifyContent: 'center',
      }}
    >
      {listing ? (
        <>
          <Chip
            label={`FOR SALE · $${listing.priceUSD}`}
            color="warning"
            size="small"
            sx={{ fontWeight: 'bold' }}
            data-testid={`${testidPrefix}-sell-tag`}
          />
          <Button
            variant="text"
            size="small"
            data-testid={`${testidPrefix}-sell-edit`}
            onClick={openSell}
          >
            Edit price
          </Button>
          <Button
            variant="text"
            size="small"
            data-testid={`${testidPrefix}-sell-unlist`}
            onClick={handleUnlist}
          >
            Unlist
          </Button>
        </>
      ) : (
        <Button
          variant="outlined"
          size="small"
          data-testid={`${testidPrefix}-sell-button`}
          onClick={openSell}
        >
          Sell
        </Button>
      )}
      <SellNavitarDialog
        target={target}
        price={price}
        error={error}
        onPriceChange={setPrice}
        onConfirm={handleConfirmSell}
        onClose={() => setTarget(null)}
      />
    </Box>
  );
};
