import React, { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Box, Button, Chip, Paper, TextField, Typography } from '@mui/material';
import { liveAiStatus } from '../utils/liveAi';
import { PlayerAvatar } from './PlayerAvatar';
import {
  NAVITAR_THREAD_ID,
  REPLY_DELAY_MS,
  appendMessage,
  ensureNavitarThread,
  getThread,
  getThreadReply,
  markThreadRead,
  type ThreadMessage,
} from '../utils/threads';
import {
  GUIDE_CHIPS,
  GUIDE_FALLBACK,
  looksLikeAsk,
  matchGuideIntent,
  type GuideEntry,
} from '../utils/guide';
import { addHelpdeskRequest } from '../utils/helpdesk';
import { addPin, pinTarget, setCompassTarget } from '../utils/compass';

export const LIVE_AI_OFF_LINE =
  'Live AI is off — your navitar answers from its scripted lines until go-live.';
export const LIVE_AI_NO_KEY_LINE =
  'Live AI is on but no DeepSeek key is configured — add it at build time. Answering from scripted lines for now.';
export const LIVE_AI_UNAVAILABLE_LINE =
  'Live AI is unavailable right now — answering from scripted lines.';

// Round 36: the helpdesk show-back's demo-honesty line — in this
// preview a confirmed request is saved on this device only; no
// support team receives it yet. Stated on the confirmation card
// itself, before the player decides.
export const HELPDESK_DEMO_NOTE =
  'In this preview the request is saved on this device only — no support team receives it yet. When GLACER is live, this is exactly what they\u2019ll get.';

interface NavitarChatProps {
  // The ACTIVE navitar: its name/portrait head the one conversation
  // (Round 36.27 — the conversation belongs to the player and does
  // not change when the active navitar does; only the picture does).
  navitar: { id?: string; name: string; element: string } | null;
  liveAiEnabled: boolean;
  // Round 36: when the chat is hosted in a closable window (the
  // Talk dialog), a guide "Take me there" tap navigates AND the
  // host closes the window. On Profile there is no window — the
  // prop is simply absent and navigation happens in place.
  onNavigateAway?: () => void;
}

// Talk to your navitar — the Profile chat IS the navitar's thread, the
// same thread the Messages page shows. The thread store
// (src/utils/threads.ts) is the source of truth: this component holds
// only a local copy of the thread's messages, refreshed from the store
// after every append, so the two views can never disagree. Replies come
// from the per-element banks in src/data/replies.ts via getThreadReply —
// element-tuned, same voice idea as the old generic lines.
//
// The toggle on the Profile page decides what happens when you send:
// - OFF (default): scripted reply only, zero network calls, zero charges.
// - ON + no key: a visible "no key configured" line, scripted reply only.
// - ON + key: the message goes to DeepSeek, reply shown in character;
//   on any failure the scripted line answers instead.
//
// Round 36 — the GUIDE + HELPDESK layer (utils/guide.ts) sits in
// front of that reply path, in the same window, over the same
// thread. It is the navitar's app knowledge as data: destinations
// with "Take me there" route actions, how-to answers, and the two
// sanctioned flows. THE PERMISSIONS LAW (Eddie, binding): the
// navitar guides, navigates, explains and points — it never
// changes settings, sends, spends or edits for the player. The
// only writes a guide turn can make are to this conversation, to
// the helpdesk outbox (only after the show-back + Send confirm),
// and to the pin store (only via the pin card's explicit Save).
export const NavitarChat: React.FC<NavitarChatProps> = ({
  navitar,
  liveAiEnabled,
  onNavigateAway,
}) => {
  const [messages, setMessages] = useState<ThreadMessage[]>([]);
  const [input, setInput] = useState('');
  const [busy, setBusy] = useState(false);
  const [unavailable, setUnavailable] = useState(false);
  // Helpdesk flow state (component-only until Send): 'awaiting' =
  // the navitar has asked for the problem; 'confirm' = the draft
  // is on its show-back card. The draft text lives HERE and
  // nowhere else — closing the window or cancelling kills it,
  // unstored, exactly per the confirmation rule.
  const [helpStage, setHelpStage] = useState<'idle' | 'awaiting' | 'confirm'>('idle');
  const [helpDraft, setHelpDraft] = useState('');
  // Pin flow state: the remember-this-spot card. A pin exists
  // only after its Save is tapped (utils/compass.ts addPin).
  const [pinOpen, setPinOpen] = useState(false);
  const [pinName, setPinName] = useState('');
  const [pinBusy, setPinBusy] = useState(false);
  const [pinError, setPinError] = useState('');
  const mountedRef = useRef(true);
  const navigate = useNavigate();

  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, []);

  // THE one navitar conversation (Round 36.27, Eddie's law): the
  // thread is the player's, keyed by nothing but itself — switching
  // the active navitar switches only the name/portrait on it, never
  // the history.
  const threadId = NAVITAR_THREAD_ID;

  // On mount (and when the navitar changes), make sure the one
  // conversation exists and load its messages from the store —
  // including the greeting and anything said on the Messages page.
  // ensureNavitarThread also folds any legacy per-navitar threads
  // into this one and re-heads it with the active navitar.
  useEffect(() => {
    if (!navitar) return;
    ensureNavitarThread({ id: navitar.id, name: navitar.name, element: navitar.element });
    const thread = getThread(threadId);
    if (thread) setMessages(thread.messages);
    // Looking at the chat = read (Round 22 Inbox read state).
    markThreadRead(threadId);
  }, [navitar]);

  // A flow in flight belongs to the moment it started in —
  // switching navitars abandons any draft/card (a draft abandoned
  // is a draft killed: it was never stored anywhere).
  useEffect(() => {
    setHelpStage('idle');
    setHelpDraft('');
    setPinOpen(false);
    setPinName('');
    setPinError('');
  }, [navitar?.id]);

  if (!navitar) {
    return (
      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h6" gutterBottom>
          Talk to your navitar
        </Typography>
        <Typography variant="body2" color="text.secondary">
          You have no navitar yet. Create one in a battle to talk to it.
        </Typography>
      </Paper>
    );
  }

  const status = liveAiEnabled ? liveAiStatus() : 'off';

  // Post one navitar line to the thread (optionally carrying a
  // guide route action) and refresh the local copy from the store.
  const navitarSay = (text: string, guide?: { label: string; route: string }) => {
    const after = appendMessage(threadId, {
      from: 'them',
      text,
      ts: Date.now(),
      ...(guide ? { guide } : {}),
    });
    if (after) {
      setMessages(after.messages);
      // The line landed in front of the player's eyes — read.
      markThreadRead(threadId);
    }
  };

  // Run one guide entry: post its answer (with its route button
  // when it has one) and open its flow when it carries one. The
  // helpdesk entry is inert while a request is already in flight
  // — re-triggering it must never orphan the draft on the
  // show-back card.
  const runGuideEntry = (entry: GuideEntry) => {
    if (entry.action?.kind === 'helpdesk' && helpStage !== 'idle') return;
    const answer = entry.answer.split('{name}').join(navitar.name);
    navitarSay(
      answer,
      entry.action?.kind === 'route'
        ? { label: entry.action.label, route: entry.action.route }
        : undefined
    );
    if (entry.action?.kind === 'helpdesk') setHelpStage('awaiting');
    if (entry.action?.kind === 'pin') {
      setPinError('');
      setPinOpen(true);
    }
  };

  const send = async () => {
    const text = input.trim();
    if (!text || busy) return;
    setInput('');

    // Helpdesk compose: this line IS the problem statement. It
    // becomes the draft on the show-back card — it is NOT posted
    // to the thread and NOT stored anywhere. Only a Send on the
    // card records anything (utils/helpdesk.ts).
    if (helpStage === 'awaiting') {
      setHelpDraft(text);
      setHelpStage('confirm');
      return;
    }

    // Your message goes into the thread store; take the returned
    // thread's messages as the new state.
    const afterYou = appendMessage(threadId, { from: 'you', text, ts: Date.now() });
    if (!afterYou) return;
    setMessages(afterYou.messages);

    // The guide layer answers first: destinations, how-tos, the
    // pin and helpdesk flows — the app's own knowledge, in front
    // of the conversational reply path (scripted or Live AI).
    const entry = matchGuideIntent(text);
    if (entry) {
      runGuideEntry(entry);
      return;
    }
    // An ask the guide doesn't know gets the honest fallback,
    // never an invented answer. Plain chatter falls through to
    // the conversation it has always had.
    if (looksLikeAsk(text)) {
      runGuideEntry(GUIDE_FALLBACK);
      return;
    }

    setBusy(true);
    setUnavailable(false);
    // Pause so the reply reads as typed, not instant — same delay as
    // the Messages page.
    await new Promise(resolve => setTimeout(resolve, REPLY_DELAY_MS));
    if (!mountedRef.current) return;
    // One reply path: scripted bank by default, DeepSeek when Live AI
    // is ON with a key, scripted fallback on a failed live call.
    const reply = await getThreadReply(afterYou, text);
    if (!mountedRef.current) return;
    const afterThem = appendMessage(threadId, {
      from: 'them',
      text: reply.text,
      ts: Date.now(),
    });
    if (afterThem) {
      setMessages(afterThem.messages);
      // The reply landed in front of the player's eyes — read.
      markThreadRead(threadId);
    }
    if (reply.liveAiUnavailable) setUnavailable(true);
    setBusy(false);
  };

  // A quick-ask chip. Ask chips speak their line as the player and
  // run the very same guide path as typing it; flow chips (pin,
  // helpdesk) open their flow directly.
  const tapChip = (entry: GuideEntry) => {
    if (busy) return;
    if (entry.action?.kind === 'pin' || entry.action?.kind === 'helpdesk') {
      runGuideEntry(entry);
      return;
    }
    if (helpStage !== 'idle') return;
    const ask = entry.chip?.ask;
    if (!ask) return;
    const afterYou = appendMessage(threadId, { from: 'you', text: ask, ts: Date.now() });
    if (!afterYou) return;
    setMessages(afterYou.messages);
    runGuideEntry(entry);
  };

  // ---- Helpdesk show-back: Send / Cancel ------------------------
  const sendHelpdesk = () => {
    const record = addHelpdeskRequest(helpDraft);
    setHelpStage('idle');
    setHelpDraft('');
    navitarSay(
      `Done \u2014 your request is saved: \u201C${record.text}\u201D. In this preview it stays on this device and no support team receives it yet; when GLACER is live, that is exactly what they\u2019ll get.`
    );
  };
  const cancelHelpdesk = () => {
    setHelpStage('idle');
    setHelpDraft('');
    navitarSay('Torn up. Nothing was sent, and nothing was saved.');
  };
  const abortHelpdesk = () => {
    setHelpStage('idle');
    navitarSay('No problem \u2014 no request started. Ask me anything else.');
  };

  // ---- Pin card: explicit Save creates the pin ------------------
  const savePin = () => {
    const name = pinName.trim() || 'My spot';
    if (!('geolocation' in navigator) || !navigator.geolocation?.getCurrentPosition) {
      setPinError(
        'This device has no location \u2014 a pin needs your real spot. Nothing was saved.'
      );
      return;
    }
    setPinBusy(true);
    // The same on-device position source the Stroll compass uses:
    // the device's own geolocation, read here, never sent.
    navigator.geolocation.getCurrentPosition(
      pos => {
        const pin = addPin(name, pos.coords.latitude, pos.coords.longitude);
        // Parity with the Stroll button path: the new pin becomes
        // the compass target.
        setCompassTarget(pinTarget(pin));
        setPinBusy(false);
        setPinOpen(false);
        setPinName('');
        setPinError('');
        navitarSay(
          `\u{1F4CC} \u201C${pin.name}\u201D \u2014 saved on this phone only, never on the shared map, never sent anywhere. Your compass in Stroll can guide you back to it.`
        );
      },
      () => {
        setPinBusy(false);
        setPinError('Location is off \u2014 a pin needs your real spot. Nothing was saved.');
      },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };
  const cancelPin = () => {
    setPinOpen(false);
    setPinName('');
    setPinError('');
  };

  const takeMeThere = (route: string) => {
    navigate(route);
    onNavigateAway?.();
  };

  return (
    <Paper sx={{ p: 3, mb: 3 }}>
      <Typography variant="h6" gutterBottom>
        Talk to {navitar.name}
      </Typography>
      {status === 'off' && (
        <Typography variant="body2" color="text.secondary" paragraph>
          {LIVE_AI_OFF_LINE}
        </Typography>
      )}
      {status === 'on-no-key' && (
        <Typography variant="body2" color="text.secondary" paragraph>
          {LIVE_AI_NO_KEY_LINE}
        </Typography>
      )}
      {unavailable && (
        <Typography variant="body2" color="text.secondary" paragraph>
          {LIVE_AI_UNAVAILABLE_LINE}
        </Typography>
      )}
      <Box sx={{ mb: 2 }}>
        {messages.length === 0 ? (
          <Typography variant="body2" color="text.secondary">
            Say something to {navitar.name} — it answers in character.
          </Typography>
        ) : (
          messages.map((m, i) => (
            <Box key={i}>
              <Typography
                variant="body2"
                paragraph
                sx={{ mb: 1 }}
                data-from={m.from === 'you' ? 'you' : 'navitar'}
              >
                {m.from === 'you' && (
                  <PlayerAvatar
                    size={18}
                    testId="navitar-chat-own-avatar"
                    style={{ verticalAlign: 'middle', marginRight: 6 }}
                  />
                )}
                <strong>{m.from === 'you' ? 'You' : navitar.name}:</strong> {m.text}
              </Typography>
              {m.guide && (
                <Button
                  size="small"
                  variant="outlined"
                  data-testid="guide-action"
                  data-route={m.guide.route}
                  onClick={() => takeMeThere(m.guide!.route)}
                  sx={{
                    ml: 3,
                    mb: 1,
                    borderRadius: '999px',
                    textTransform: 'none',
                    fontWeight: 700,
                  }}
                >
                  🧭 {m.guide.label}
                </Button>
              )}
            </Box>
          ))
        )}
      </Box>

      {/* Helpdesk: waiting for the problem statement. */}
      {helpStage === 'awaiting' && (
        <Paper
          variant="outlined"
          data-testid="helpdesk-awaiting"
          sx={{ p: 1.5, mb: 2, borderRadius: '14px' }}
        >
          <Typography variant="body2" sx={{ mb: 0.5 }}>
            Tell me what&rsquo;s wrong below, in your own words. I&rsquo;ll show you the exact
            request before anything is sent — nothing is sent until you tap Send.
          </Typography>
          <Button size="small" onClick={abortHelpdesk} data-testid="helpdesk-abort">
            Never mind
          </Button>
        </Paper>
      )}

      {/* Helpdesk: the show-back. The draft on this card is the
          exact text a Send would record — verbatim, or it doesn't
          ship. */}
      {helpStage === 'confirm' && (
        <Paper
          variant="outlined"
          data-testid="helpdesk-confirm"
          sx={{ p: 1.5, mb: 2, borderRadius: '14px' }}
        >
          <Typography variant="body2" sx={{ fontWeight: 700, mb: 0.5 }}>
            Here&rsquo;s exactly what I&rsquo;ll send:
          </Typography>
          <Typography
            variant="body2"
            data-testid="helpdesk-draft"
            sx={{
              whiteSpace: 'pre-wrap',
              bgcolor: 'action.hover',
              borderRadius: '10px',
              p: 1,
              mb: 1,
            }}
          >
            {helpDraft}
          </Typography>
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
            {HELPDESK_DEMO_NOTE}
          </Typography>
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button
              variant="contained"
              size="small"
              onClick={sendHelpdesk}
              data-testid="helpdesk-send"
            >
              Send
            </Button>
            <Button
              variant="outlined"
              size="small"
              onClick={cancelHelpdesk}
              data-testid="helpdesk-cancel"
            >
              Cancel
            </Button>
          </Box>
        </Paper>
      )}

      {/* Pin card: a pin is created ONLY by this card's Save. */}
      {pinOpen && (
        <Paper
          variant="outlined"
          data-testid="pin-card"
          sx={{ p: 1.5, mb: 2, borderRadius: '14px' }}
        >
          <Typography variant="body2" sx={{ fontWeight: 700, mb: 1 }}>
            📍 Remember this spot
          </Typography>
          <TextField
            fullWidth
            size="small"
            label="Name this spot"
            placeholder="My car"
            value={pinName}
            onChange={e => setPinName(e.target.value)}
            inputProps={{ 'data-testid': 'pin-name-input' }}
            sx={{ mb: 1 }}
          />
          {pinError && (
            <Typography variant="body2" color="error" data-testid="pin-error" sx={{ mb: 1 }}>
              {pinError}
            </Typography>
          )}
          <Box sx={{ display: 'flex', gap: 1 }}>
            <Button
              variant="contained"
              size="small"
              onClick={savePin}
              disabled={pinBusy}
              data-testid="pin-save"
            >
              Save pin
            </Button>
            <Button variant="outlined" size="small" onClick={cancelPin} data-testid="pin-cancel">
              Cancel
            </Button>
          </Box>
        </Paper>
      )}

      {/* Guide quick-asks. */}
      <Box data-testid="guide-chips" sx={{ display: 'flex', gap: 0.75, flexWrap: 'wrap', mb: 1.5 }}>
        {GUIDE_CHIPS.map(entry => (
          <Chip
            key={entry.id}
            label={entry.chip!.label}
            size="small"
            clickable
            onClick={() => tapChip(entry)}
            data-testid={`guide-chip-${entry.id}`}
            sx={{ fontWeight: 600 }}
          />
        ))}
      </Box>

      <Box sx={{ display: 'flex', gap: 1 }}>
        <TextField
          fullWidth
          size="small"
          label={helpStage === 'awaiting' ? 'Describe the problem' : `Message ${navitar.name}`}
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyDown={e => {
            if (e.key === 'Enter') void send();
          }}
          disabled={busy}
        />
        <Button variant="contained" onClick={() => void send()} disabled={busy || !input.trim()}>
          Send
        </Button>
      </Box>
    </Paper>
  );
};
