// Promoted venue PRODUCER (Round 29, sim §14) — headless.
//
// Recognized partners buy REACH: beyond the normal suggestion
// radius, a Recognized venue with something on may surface as a
// promoted pop-up suggestion. The discipline mirrors the venue
// notice producer (VenueNotification.tsx) — same trigger shape
// (a check-in or a page move arms one suggestion, never a timer
// blast), same one-system rule (the pop-up is a notifications
// store record; NotificationToasts renders it, /notifications
// keeps it) — plus the §14 hard rules the paid tier lives under:
//
// - LABELLED: the record says "Worth the Trip" and "Recognized ·
//   Paid partner" out loud. Paid reach is never disguised as an
//   organic suggestion.
// - RELEVANCE-FILTERED: only a venue with something on — an
//   event tonight or a live perk of its own (utils/venuePerks
//   venueHasSomethingOn). A Recognized venue with neither (the
//   demo's Griffith Park) is never promoted.
// - CAPPED: max 2 promoted pop-ups per player per day, enforced
//   by the persisted counter in the perks store — the cap is a
//   store fact, not a session mood.
// - MUTABLE: the player's mute (the Worth the Trip feed's
//   switch) stops promoted pop-ups entirely and persists. It
//   never touches normal nearby discovery.
// - ONE-WAY: a suggestion reveals nothing about any player to
//   any venue. Venue-side reporting is Round 30, not this.
//
// The record is kind 'venue' so a tap takes the existing venue
// landing (map focus on that venue); its id lives in its own
// `promoted-…` space and carries no sourceId, so the venue
// notices' per-day dismissal never reaches back into it.
import React, { useEffect, useRef, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { DEMO_VENUES, type DemoVenue } from '../data/venues';
import { buzzForVenue } from '../data/venueBuzz';
import { useNotifications } from '../contexts/NotificationsContext';
import { useVenue } from '../contexts/VenueContext';
import { loadNotifications } from '../utils/notifications';
import { localDateString } from '../utils/presence';
import {
  PROMOTED_DAILY_CAP,
  RECOGNIZED_SUGGESTION_RADIUS_MI,
  distanceMi,
  isRecognizedVenue,
  promotedCountToday,
  promotedMuted,
  recordPromotedShown,
  suggestionAnchor,
  typeBPerksForVenue,
  typeBStatus,
  venueHasSomethingOn,
} from '../utils/venuePerks';

function whatsOnLine(venue: DemoVenue): string {
  const buzz = buzzForVenue(venue.id);
  if (buzz?.event) return `${buzz.event.name} — ${buzz.event.when}.`;
  const live = typeBPerksForVenue(venue.id).find(p => typeBStatus(p) === 'available');
  if (live) return `The venue's own perk is on: ${live.item.toLowerCase()}.`;
  return 'Something is on tonight.';
}

const PromotedVenueProducer: React.FC = () => {
  const location = useLocation();
  const { notify } = useNotifications();
  const { checkedInVenueId } = useVenue();
  const [shownCount, setShownCount] = useState(0);
  const [armed, setArmed] = useState(false);
  const triggerRef = useRef<string>('');

  const trigger = `${location.pathname}|${checkedInVenueId ?? 'none'}`;
  useEffect(() => {
    if (triggerRef.current !== trigger) {
      triggerRef.current = trigger;
      setShownCount(0);
      setArmed(false);
      const t = window.setTimeout(() => setArmed(true), 1200);
      return () => window.clearTimeout(t);
    }
    return undefined;
  }, [trigger]);
  useEffect(() => {
    const t = window.setTimeout(() => setArmed(true), 2500);
    return () => window.clearTimeout(t);
  }, []);

  useEffect(() => {
    if (!armed || shownCount >= 1) return;
    if (promotedMuted()) return;
    if (promotedCountToday() >= PROMOTED_DAILY_CAP) return;
    const today = localDateString();
    const existing = loadNotifications();
    const anchor = suggestionAnchor(checkedInVenueId);
    const candidate = DEMO_VENUES.find(v => {
      if (!isRecognizedVenue(v.id)) return false;
      if (!venueHasSomethingOn(v)) return false;
      if (distanceMi(anchor, v) > RECOGNIZED_SUGGESTION_RADIUS_MI) return false;
      return !existing.some(n => n.id === `promoted-${v.id}-${today}`);
    });
    if (!candidate) return;
    notify({
      id: `promoted-${candidate.id}-${today}`,
      kind: 'venue',
      title: `⭐ Worth the Trip: ${candidate.name}`,
      body: `${whatsOnLine(candidate)} Recognized · Paid partner — a promoted suggestion from across the city (demo).`,
      route: '/map',
      venueId: candidate.id,
      demo: true,
    });
    recordPromotedShown();
    setShownCount(c => c + 1);
  }, [armed, shownCount, checkedInVenueId, notify]);

  return null;
};

export default PromotedVenueProducer;
