// ---- Group read state (Round 22) -----------------------------------
// Group chats live in the social store (above), not the threads
// store, so their read stamps live in a small side map. Same rule
// as threads: no stamp = legacy = history counts as read, and the
// migration stamps on first sight.
export const GROUP_READ_KEY = 'glacer-group-last-read';

export function loadGroupLastRead(): Record<string, number> {
  try {
    const raw = localStorage.getItem(GROUP_READ_KEY);
    if (!raw) return {};
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== 'object') return {};
    const out: Record<string, number> = {};
    for (const [k, v] of Object.entries(parsed as Record<string, unknown>)) {
      if (typeof v === 'number') out[k] = v;
    }
    return out;
  } catch {
    return {};
  }
}

function saveGroupLastRead(map: Record<string, number>): void {
  try {
    localStorage.setItem(GROUP_READ_KEY, JSON.stringify(map));
  } catch {
    // Private mode / quota: badges still compute for the session.
  }
  try {
    window.dispatchEvent(new Event(SOCIAL_CHANGED_EVENT));
  } catch {
    // Non-browser context (tests): nothing to notify.
  }
}

export function groupUnreadCount(group: DemoGroup, readMap: Record<string, number>): number {
  const stamp = readMap[group.id];
  if (typeof stamp !== 'number') return 0;
  return group.messages.filter(m => m.from !== 'you' && m.ts > stamp).length;
}

export function migrateGroupReadState(groups: DemoGroup[]): void {
  const map = loadGroupLastRead();
  let changed = false;
  for (const g of groups) {
    if (typeof map[g.id] === 'number') continue;
    changed = true;
    const last = g.messages[g.messages.length - 1];
    map[g.id] = last ? last.ts : 0;
  }
  if (changed) saveGroupLastRead(map);
}

export function markGroupRead(groupId: string): void {
  const state = loadSocial();
  const group = state.groups.find(g => g.id === groupId);
  const last = group?.messages[group.messages.length - 1];
  const stamp = Math.max(Date.now(), last ? last.ts : 0);
  const map = loadGroupLastRead();
  if (map[groupId] === stamp) return;
  map[groupId] = stamp;
  saveGroupLastRead(map);
}

// Resolve a pending friend request with the simulated answer. An
// accept is the ONLY path that adds the person to glacer-friends.
export function resolveFriendRequest(
  state: SocialState,
  personId: string
): { state: SocialState; accepted: boolean } {
  const accepted = demoAccepts(`friend-request:${personId}`);
  if (accepted) recordMetFriend(personId);
  return {
    state: {
      ...state,
      requests: { ...state.requests, [personId]: accepted ? 'accepted' : 'declined' },
    },
    accepted,
  };
}

// ---- Incoming requests (Round 26) -----------------------------------
// Seed the demo's incoming requests exactly once per device: the
// first time the store is seen unseeded, up to two demo people —
// not friends, not blocked, with no outgoing request on file —
// have "sent" the player a friend request. The pick is
// deterministic (so a phone test is repeatable): the LAST two
// eligible people in realm order — the far end of the map, people
// a fresh player hasn't run into yet. (It also leaves the map's
// first greeter free to be asked: Maya's outgoing-request flow is
// the Round 17-proven path and stays exactly as it was.) The
// IncomingRequestProducer calls this and announces each seeded
// request with a TYPE-ONLY notification (title = type + sender's
// handle; a friend request carries no message text, ever).
export function seedIncomingRequests(state: SocialState): {
  state: SocialState;
  seededIds: string[];
} {
  if (state.incomingSeeded) return { state, seededIds: [] };
  const friendIds = new Set(loadFriends());
  const seededIds = allDemoPeople()
    .filter(
      e =>
        !friendIds.has(e.person.id) &&
        !state.blocked.includes(e.person.id) &&
        !state.requests[e.person.id] &&
        !state.incoming[e.person.id]
    )
    .slice(-2)
    .map(e => e.person.id);
  const incoming = { ...state.incoming };
  for (const id of seededIds) incoming[id] = 'pending';
  return { state: { ...state, incoming, incomingSeeded: true }, seededIds };
}

// Accept an incoming request: the SAME friend write an accepted
// outgoing request makes (recordMetFriend) — one friends list,
// however the friendship started.
export function acceptIncomingRequest(state: SocialState, personId: string): SocialState {
  if (state.incoming[personId] !== 'pending') return state;
  recordMetFriend(personId);
  return { ...state, incoming: { ...state.incoming, [personId]: 'accepted' } };
}

// Decline an incoming request: the request clears, quietly — no
// notification drama in either direction (Round 26 brief).
export function declineIncomingRequest(state: SocialState, personId: string): SocialState {
  if (state.incoming[personId] !== 'pending') return state;
  return { ...state, incoming: { ...state.incoming, [personId]: 'declined' } };
}

export function friendIdsNow(): string[] {
  return loadFriends();
}

// ---- Home kickbacks -------------------------------------------------
// The home's NAME and the host's chosen visibility list persist
// (that is the host's own setting). Who was at a kickback NEVER
// persists — session attendance lives in page state only and is
// wiped when the session ends (see pages/Kickback.tsx and
// files/home-kickback-venues-spec.md).

export interface KickbackHome {
  name: string;
  visibleTo: string[];
}

export function loadKickbackHome(): KickbackHome | null {
  try {
    const raw = localStorage.getItem(KICKBACK_HOME_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as Partial<KickbackHome>;
    if (typeof parsed.name !== 'string' || parsed.name.trim() === '') return null;
    return {
      name: parsed.name,
      visibleTo: Array.isArray(parsed.visibleTo)
        ? parsed.visibleTo.filter((v): v is string => typeof v === 'string')
        : [],
    };
  } catch {
    return null;
  }
}

export function saveKickbackHome(home: KickbackHome): void {
  try {
    localStorage.setItem(KICKBACK_HOME_KEY, JSON.stringify(home));
  } catch {
    // Private mode / quota: the setting still holds for this session.
  }
}

export function removeKickbackHome(): void {
  try {
    localStorage.removeItem(KICKBACK_HOME_KEY);
  } catch {
    // Nothing to remove.
  }
}
