// Catches render errors in one route so a broken page shows a fallback
// instead of unmounting the whole app (blank/black screen with no nav).
// Added after /realm crashed the entire tree because a Leaflet hook was
// used outside its MapContainer — without a boundary, one bad page killed
// every page, including back-navigation.
import React from 'react';
import { Box, Typography, Button, CircularProgress } from '@mui/material';
import { recoverFromChunkError } from '../utils/chunkRecovery';

interface ErrorBoundaryProps {
  children: React.ReactNode;
}

interface ErrorBoundaryState {
  error: Error | null;
  // Round 31: the error was a stale lazy chunk after a redeploy and
  // a one-time recovery reload is already in flight — show the
  // updating state, not the error page.
  recovering?: boolean;
}

class ErrorBoundary extends React.Component<ErrorBoundaryProps, ErrorBoundaryState> {
  constructor(props: ErrorBoundaryProps) {
    super(props);
    this.state = { error: null };
  }

  static getDerivedStateFromError(error: Error): ErrorBoundaryState {
    return { error };
  }

  componentDidCatch(error: Error, info: React.ErrorInfo) {
    console.error('ErrorBoundary caught:', error, info.componentStack);
    // Round 31 chunk self-recovery: a "Loading chunk N failed" here
    // means the page's chunk map is stale after a redeploy — reload
    // once for the fresh build instead of stranding the player on
    // the error page. recoverFromChunkError guards the loop.
    if (recoverFromChunkError(error)) {
      this.setState({ recovering: true });
    }
  }

  render() {
    if (this.state.recovering) {
      return (
        <Box sx={{ py: 6, textAlign: 'center' }} data-testid="chunk-recovering">
          <CircularProgress sx={{ mb: 2 }} />
          <Typography variant="h6" gutterBottom>
            Updating GLACER…
          </Typography>
          <Typography variant="body2" color="text.secondary">
            A new version just landed — fetching it now.
          </Typography>
        </Box>
      );
    }
    if (this.state.error) {
      return (
        <Box sx={{ py: 4, textAlign: 'center' }}>
          <Typography variant="h5" gutterBottom>
            Something went wrong on this page
          </Typography>
          <Typography variant="body1" color="text.secondary" paragraph>
            {this.state.error.message}
          </Typography>
          <Button variant="contained" onClick={() => this.setState({ error: null })}>
            Try again
          </Button>
        </Box>
      );
    }
    return this.props.children;
  }
}

export default ErrorBoundary;
