// Friends-only real presence (P2.2b) — Supabase Realtime Presence,
// scoped to accepted friends, under the presence law:
//
// - A player broadcasts ONLY their networking status (Open to meet
//   / Battle-ready / Just here) — never a location, never anything
//   else. Presence is a status, not a position.
// - Invisible means invisible, absolutely: a player whose
//   visibility is 'invisible' never tracks presence at all —
//   nothing is emitted, so there is nothing to show. (They can
//   still look around: subscribing to a friend's channel emits
//   nothing of theirs.)
// - Presence is only ever READ about accepted friends: the app
//   subscribes to one presence channel per accepted friend
//   (glacer-presence-<userId>) and to no one else's. Strangers are
//   never subscribed to, never shown. A friend's status is shown
//   to me only when THEIR visibility permits a friend to see it
//   ('venue' / 'friends'); 'business' (business contacts only) and
//   'invisible' read as absent — enforced again here on the read
//   side, so even a client that tracked when it shouldn't have is
//   not surfaced.
// - Nothing is stored: presence lives in the channel and dies with
//   it. No table, no history, no admin surface can see it — the
//   no-admin-live-tracking law holds by construction.
//
// Transport: one channel per user, presence key = the user id.
// The owner publishes on their own channel; each friend who wants
// to see them subscribes to it. Channel names carry only the user
// id, which friends already know from the profiles table.
import { useEffect, useRef, useState } from 'react';
import { supabase } from './supabaseClient';
import type { RealtimeChannel } from '@supabase/supabase-js';
import type { NetworkingStatus, VisibilityScope } from './presence';

interface PresenceMeta {
  user_id: string;
  status: NetworkingStatus;
  visibility: VisibilityScope;
  online_at: string;
}

type Listener = (map: Map<string, NetworkingStatus>) => void;

const VISIBLE_TO_FRIENDS: ReadonlySet<VisibilityScope> = new Set(['venue', 'friends']);

class FriendPresenceManager {
  private myId: string | null = null;
  private myStatus: NetworkingStatus = 'open';
  private myVisibility: VisibilityScope = 'venue';
  private publishChannel: RealtimeChannel | null = null;
  private readChannels = new Map<string, RealtimeChannel>();
  private wanted = new Map<string, number>(); // friendId -> refcount
  private visible = new Map<string, NetworkingStatus>();
  private listeners = new Set<Listener>();

  subscribe(listener: Listener): () => void {
    this.listeners.add(listener);
    listener(new Map(this.visible));
    return () => {
      this.listeners.delete(listener);
    };
  }

  private emit(): void {
    const snapshot = new Map(this.visible);
    this.listeners.forEach(l => l(snapshot));
  }

  // The signed-in player + their presence settings. Called by the
  // hook whenever any of them change; cheap to call redundantly.
  configure(myId: string | null, status: NetworkingStatus, visibility: VisibilityScope): void {
    const identityChanged = myId !== this.myId;
    const settingsChanged = status !== this.myStatus || visibility !== this.myVisibility;
    this.myId = myId;
    this.myStatus = status;
    this.myVisibility = visibility;
    if (identityChanged) {
      // A different player (or sign-out): every channel belongs to
      // the old identity — tear down and rebuild for the new one.
      this.teardownChannels();
      this.visible.clear();
      this.emit();
    }
    if (identityChanged || settingsChanged) this.syncPublish();
    if (identityChanged) this.syncReads();
  }

  // Components register interest in friends' presence; the manager
  // keeps exactly one read channel per wanted friend.
  want(friendIds: string[]): () => void {
    const added: string[] = [];
    for (const id of friendIds) {
      if (!id || id === this.myId) continue;
      this.wanted.set(id, (this.wanted.get(id) ?? 0) + 1);
      added.push(id);
    }
    this.syncReads();
    return () => {
      for (const id of added) {
        const next = (this.wanted.get(id) ?? 1) - 1;
        if (next <= 0) this.wanted.delete(id);
        else this.wanted.set(id, next);
      }
      this.syncReads();
    };
  }

  private teardownChannels(): void {
    if (this.publishChannel) {
      const ch = this.publishChannel;
      this.publishChannel = null;
      void supabase.removeChannel(ch).catch(() => undefined);
    }
    for (const ch of this.readChannels.values()) {
      void supabase.removeChannel(ch).catch(() => undefined);
    }
    this.readChannels.clear();
  }

  private syncPublish(): void {
    // Invisible (or signed out): emit nothing. An existing publish
    // channel is torn down so the presence is withdrawn at once.
    if (!this.myId || this.myVisibility === 'invisible') {
      if (this.publishChannel) {
        const ch = this.publishChannel;
        this.publishChannel = null;
        void supabase.removeChannel(ch).catch(() => undefined);
      }
      return;
    }
    if (!this.publishChannel) {
      const channel = supabase.channel(`glacer-presence-${this.myId}`, {
        config: { presence: { key: this.myId } },
      });
      this.publishChannel = channel;
      void channel.subscribe(async status => {
        if (status === 'SUBSCRIBED' && this.publishChannel === channel) {
          await channel.track(this.meta());
        }
      });
      return;
    }
    // Already publishing: re-track with the fresh settings.
    void this.publishChannel.track(this.meta()).catch(() => undefined);
  }

  private meta(): PresenceMeta {
    return {
      user_id: this.myId ?? '',
      status: this.myStatus,
      visibility: this.myVisibility,
      online_at: new Date().toISOString(),
    };
  }

  private syncReads(): void {
    if (!this.myId) {
      // Signed out: no reads at all.
      for (const [id, ch] of this.readChannels) {
        void supabase.removeChannel(ch).catch(() => undefined);
        this.readChannels.delete(id);
        if (this.visible.delete(id)) this.emit();
      }
      return;
    }
    // Drop channels for friends nobody wants any more.
    for (const [id, ch] of this.readChannels) {
      if (!this.wanted.has(id)) {
        void supabase.removeChannel(ch).catch(() => undefined);
        this.readChannels.delete(id);
        if (this.visible.delete(id)) this.emit();
      }
    }
    // Open channels for newly wanted friends.
    for (const id of this.wanted.keys()) {
      if (this.readChannels.has(id)) continue;
      const channel = supabase.channel(`glacer-presence-${id}`, {
        config: { presence: { key: `watcher-${this.myId}` } },
      });
      this.readChannels.set(id, channel);
      const apply = () => {
        const state = channel.presenceState<PresenceMeta>();
        const metas = state[id] ?? [];
        const meta = metas[0];
        const showable = meta && VISIBLE_TO_FRIENDS.has(meta.visibility) ? meta.status : null;
        if (showable) {
          if (this.visible.get(id) !== showable) {
            this.visible.set(id, showable);
            this.emit();
          }
        } else if (this.visible.delete(id)) {
          this.emit();
        }
      };
      channel
        .on('presence', { event: 'sync' }, apply)
        .on('presence', { event: 'join' }, apply)
        .on('presence', { event: 'leave' }, apply);
      void channel.subscribe();
    }
  }
}

export const friendPresence = new FriendPresenceManager();

// React hook: wires the manager to the caller's identity/settings
// and the friend ids on screen, and returns the visible-status map
// (friendId -> status) for exactly the friends asked about.
// Callers pass their accepted friends' ids; strangers are never
// asked about, so they are never subscribed to.
export function useFriendPresence(
  myId: string | null,
  myStatus: NetworkingStatus,
  myVisibility: VisibilityScope,
  friendIds: string[]
): Map<string, NetworkingStatus> {
  const [map, setMap] = useState<Map<string, NetworkingStatus>>(new Map());
  const idsKey = [...friendIds].sort().join(',');
  const idsRef = useRef<string[]>([]);
  idsRef.current = idsKey ? idsKey.split(',') : [];

  useEffect(() => friendPresence.subscribe(setMap), []);
  useEffect(() => {
    friendPresence.configure(myId, myStatus, myVisibility);
  }, [myId, myStatus, myVisibility]);
  useEffect(() => friendPresence.want(idsRef.current), [idsKey]);

  return map;
}
