import { useEffect, useState } from 'react';

// Favorite navitars (Round 36.10 Part C, Eddie 2026-11-20 ~14:22
// PT: "they can set favorites"). ONE store for the whole app:
// the ★ on a card (the Navidex Stage's card, the deck's front
// card, the grid twin — the same NavitarDesign component) marks
// or unmarks a fighter here, and every card hears the change
// through the one window event below, so no two surfaces can
// disagree about whether a fighter is a favorite.
//
// On-device only, like the other demo-layer stores (care,
// threads, moderation): the names live in localStorage under
// FAVORITES_KEY and never leave the phone. Order in the store
// is tap order; surfaces that cycle favorites (the deck) read
// them in roster order instead.
export const FAVORITES_KEY = 'glacer-favorite-navitars';
export const FAVORITES_EVENT = 'glacer-favorites-changed';

export function getFavorites(): string[] {
  try {
    const raw = localStorage.getItem(FAVORITES_KEY);
    const parsed: unknown = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed.filter((n): n is string => typeof n === 'string') : [];
  } catch {
    return [];
  }
}

export function isFavorite(name: string): boolean {
  return getFavorites().includes(name);
}

export function setFavorite(name: string, fav: boolean): string[] {
  const cur = getFavorites();
  const next = fav ? (cur.includes(name) ? cur : [...cur, name]) : cur.filter(n => n !== name);
  try {
    localStorage.setItem(FAVORITES_KEY, JSON.stringify(next));
  } catch {
    // Private mode / quota: the change still applies for the
    // session through the event below.
  }
  window.dispatchEvent(new CustomEvent<string[]>(FAVORITES_EVENT, { detail: next }));
  return next;
}

export function toggleFavorite(name: string): string[] {
  return setFavorite(name, !isFavorite(name));
}

// The React face of the store: the current favorite names, live
// across every mounted card (the change event) and across tabs
// (the storage event).
export function useFavorites(): string[] {
  const [favorites, setFavorites] = useState<string[]>(() => getFavorites());
  useEffect(() => {
    const onChange = (e: Event) => {
      const detail = (e as CustomEvent<string[]>).detail;
      setFavorites(Array.isArray(detail) ? detail : getFavorites());
    };
    const onStorage = (e: StorageEvent) => {
      if (e.key === FAVORITES_KEY) setFavorites(getFavorites());
    };
    window.addEventListener(FAVORITES_EVENT, onChange);
    window.addEventListener('storage', onStorage);
    return () => {
      window.removeEventListener(FAVORITES_EVENT, onChange);
      window.removeEventListener('storage', onStorage);
    };
  }, []);
  return favorites;
}
